window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[162]={"id":"162","numero":162,"titre":"Infections sexuellement transmissibles (IST)","objectifs":[{"id":"162-1","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes des infections sexuellement transmissibles (IST) selon leur expression clinique","contenu":"<p>Les <span class=\"kw-def\">IST</span> se classent selon <strong>3 paramètres</strong> : le type de <span class=\"kw-def\">manifestation</span> (<span class=\"kw-clinique\">ulcération</span> <span class=\"kw-bio\">vs</span> inflammation loco-régionale), la <span class=\"kw-def\">sphère d'expression</span> (génitale, extra-génitale ou mixte) et le <span class=\"kw-def\">sexe</span>.</p>\n      <table >\n        <thead><tr><th>Expression clinique</th><th>Germes en cause</th></tr></thead>\n        <tbody>\n          <tr><th>Ulcérations cutanéo-muqueuses<br><em>(↑ transmission du <span class=\"kw-etio\">VIH</span>)</em></th><td><span class=\"kw-etio\">Syphilis</span> (<em>Treponema pallidum</em>) ; <span class=\"kw-etio\">HSV</span> ; <span class=\"kw-etio\">Chlamydia trachomatis</span> de <span class=\"kw-def\">génotype L</span> (LGV)</td></tr>\n          <tr><th>Inflammation loco-régionale<br><em>(écoulement)</em></th><td><span class=\"kw-etio\">Gonocoque</span> ; <span class=\"kw-etio\">Chlamydia trachomatis D–K</span> ; <span class=\"kw-etio\">Trichomonas vaginalis</span> ; <span class=\"kw-etio\">Mycoplasma genitalium</span> → urétrite, prostatite, orchite, cervicite, endométrite, salpingite, rectite</td></tr>\n          <tr><th>Sphère d'expression</th><td><strong>Génitale :</strong> herpès, gonocoque, Chlamydia<br><strong>Extra-génitale :</strong> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span><br><strong>Mixte :</strong> syphilis (cas particulier)</td></tr>\n        </tbody>\n      </table>\n      <p>Par famille d'agents : <strong>virus</strong> = <span class=\"kw-etio\">HPV</span> (le plus fréquent), <span class=\"kw-etio\">HSV</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span> ; <strong>bactéries</strong> = <span class=\"kw-etio\">Chlamydia trachomatis</span> (<strong>1ʳᵉ cause d'IST <span class=\"kw-etio\">bactérienne</span></strong>), <span class=\"kw-etio\">gonocoque</span>, <span class=\"kw-etio\">Treponema pallidum</span>, <span class=\"kw-etio\">Mycoplasma genitalium</span> ; <strong>parasites</strong> = <span class=\"kw-etio\">Trichomonas vaginalis</span>, <span class=\"kw-etio\">gale</span>, <span class=\"kw-etio\">phtirose pubienne</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Ne sont PAS des IST.</strong> <span class=\"kw-clinique\">Candidose vaginale</span> (<span class=\"kw-etio\">Candida albicans</span>), <span class=\"kw-clinique\">vaginose bactérienne</span> (<span class=\"kw-etio\">Gardnerella vaginalis</span>, <span class=\"kw-etio\">M. hominis</span>), <span class=\"kw-clinique\">orchite à entérobactérie</span> : déséquilibres de flore ou acquisition non sexuelle, pas de contamination externe.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales</em></p>","frequence":2},{"id":"162-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence des différentes IST et leurs facteurs de risque","contenu":"<p><span class=\"kw-etio\">Chlamydia trachomatis</span> est la <strong>1ʳᵉ cause d'IST <span class=\"kw-etio\">bactérienne</span></strong> dans les pays industrialisés (<span class=\"kw-def\">prévalence</span> ≈ <span class=\"kw-chiffre\">10 %</span>), environ <span class=\"kw-chiffre\">50×</span> plus fréquente que la gonococcie. La <span class=\"kw-etio\">gonococcie</span> et la <span class=\"kw-etio\">syphilis</span> sont <strong>en augmentation</strong>, surtout chez les <span class=\"kw-clinique\">HSH</span> (syphilis &gt;<span class=\"kw-chiffre\"> 80 %</span> des cas, souvent co-infection <span class=\"kw-etio\">VIH</span> ≈<span class=\"kw-chiffre\"> 40 %</span>).</p>\n      <ul>\n        <li><span class=\"kw-etio\">Chlamydia</span> génotype <span class=\"kw-def\">D–K</span> : <span class=\"kw-clinique\">cervicites</span>/<span class=\"kw-clinique\">urétrites</span> de la <span class=\"kw-clinique\">femme &lt; 25 ans</span> ; génotype <span class=\"kw-def\">L1–L3</span> (LGV) : quasi exclusivement <span class=\"kw-clinique\">HSH VIH+</span></li>\n        <li><span class=\"kw-etio\">Gonocoque</span> : en hausse chez <span class=\"kw-clinique\">hétérosexuels</span> et surtout <span class=\"kw-clinique\">HSH</span></li>\n        <li><span class=\"kw-etio\">Trichomonas</span> : fréquent en <span class=\"kw-clinique\">Afrique</span> et aux <span class=\"kw-clinique\">Caraïbes</span></li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> :</strong></p>\n      <ul>\n        <li><strong>Comportementaux :</strong> <span class=\"kw-etio\">multiplicité des partenaires</span> ; <span class=\"kw-etio\">rapports non protégés</span> ; <span class=\"kw-etio\">jeune âge et précocité des rapports</span> ; <span class=\"kw-etio\">prostitution</span></li>\n        <li><strong>Sociaux / <span class=\"kw-def\">terrain</span> :</strong> <span class=\"kw-etio\">bas niveau socio-économique</span> ; <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">drogue</span> ; <span class=\"kw-etio\">incarcération</span> ; <span class=\"kw-etio\">ATCD d'IST</span></li>\n      </ul>","frequence":1},{"id":"162-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures préventives des IST","contenu":"<p>Prévention combinant des mesures <span class=\"kw-def\">individuelles</span> et de <span class=\"kw-def\">santé publique</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Préservatifs</span> <span class=\"kw-clinique\">masculins</span> et <span class=\"kw-clinique\">féminins</span> (prévention de référence)</li>\n        <li><span class=\"kw-clinique\">Dépistage régulier</span> en cas d'expositions répétées + <span class=\"kw-clinique\">éducation</span> et <span class=\"kw-clinique\">notification aux partenaires</span></li>\n        <li><strong>Vaccinations :</strong> <span class=\"kw-ttt\">HPV</span>, <span class=\"kw-ttt\">VHB</span>, <span class=\"kw-ttt\">VHA</span> (à proposer aux <span class=\"kw-clinique\">HSH</span> — contamination par <span class=\"kw-clinique\">rapports bucco-anaux</span>)</li>\n        <li><span class=\"kw-ttt\">PrEP</span> (<span class=\"kw-def\">prophylaxie pré-exposition</span>) anti-<span class=\"kw-etio\">VIH</span> si prises de risque régulières</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Toute consultation pour <span class=\"kw-def\">IST</span> est une occasion de proposer le <span class=\"kw-def\">dépistage</span> <span class=\"kw-bio\">VIH</span> / <span class=\"kw-bio\">syphilis</span> / <span class=\"kw-bio\">VHB</span> et de vérifier le <span class=\"kw-clinique\">statut vaccinal</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales · 146 — Vaccination</em></p>","frequence":1},{"id":"162-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge du ou des partenaires","contenu":"<p>Les <strong>partenaires sont systématiquement dépistés</strong>, et selon le germe, traités en probabiliste :</p>\n      <table >\n        <thead><tr><th>IST</th><th>Conduite vis-à-vis du partenaire</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">Chlamydia</span></th><td><span class=\"kw-ttt\">Traitement d'emblée</span> du/des partenaire(s) régulier(s)</td></tr>\n          <tr><th><span class=\"kw-etio\">Gonocoque</span></th><td><span class=\"kw-clinique\">Dépistage</span> des partenaires ± traitement antibiotique</td></tr>\n          <tr><th><span class=\"kw-etio\">Syphilis</span></th><td><span class=\"kw-ttt\">Traitement d'emblée</span> si <span class=\"kw-chiffre\">dernier rapport &lt; 6 semaines</span> ; sinon <span class=\"kw-bio\">sérologie</span> et traitement si positive</td></tr>\n          <tr><th><span class=\"kw-etio\">HPV</span></th><td>Pas de <span class=\"kw-def\">dépistage</span> particulier (indications de dépistage indépendantes des rapports récents)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Syphilis — détail selon le sujet source :</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">Dernier rapport &lt; 6 sem</span> + <span class=\"kw-clinique\">syphilis certaine</span> : <span class=\"kw-ttt\">1 injection IM de pénicilline G retard</span> d'emblée (puis <span class=\"kw-bio\">sérologie</span>)</li>\n        <li><span class=\"kw-chiffre\">Dernier rapport &gt; 6 sem</span> ou <span class=\"kw-clinique\">syphilis douteuse</span> : <span class=\"kw-bio\">sérologie</span> → traiter si positive, sinon recontrôle à <span class=\"kw-chiffre\">M3</span></li>\n      </ul>","frequence":1},{"id":"162-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes des ulcérations génitales infectieuses ou non infectieuses","contenu":"<p>Une <span class=\"kw-def\">ulcération génitale</span> = perte de substance muqueuse/cutanée, unique ou multiple. Elle <strong>augmente la transmission sexuelle du <span class=\"kw-etio\">VIH</span></strong>.</p>\n      <table >\n        <thead><tr><th></th><th>Herpès</th><th>Syphilis</th><th>LGV (Nicolas-Favre)</th><th>Chancre mou</th><th>Donovanose</th></tr></thead>\n        <tbody>\n          <tr><th>Germe</th><td><span class=\"kw-etio\">HSV2</span> (2/3), HSV1</td><td><span class=\"kw-etio\">T. pallidum</span></td><td><span class=\"kw-etio\">C. trachomatis L</span></td><td><span class=\"kw-etio\">H. ducreyi</span></td><td><span class=\"kw-etio\">K. granulomatis</span></td></tr>\n          <tr><th>Douleur</th><td><span class=\"kw-clinique\">Douloureux</span></td><td><span class=\"kw-clinique\">Indolore</span></td><td><span class=\"kw-clinique\">Indolore</span> (génital), <span class=\"kw-clinique\">douleur</span> (anal)</td><td><span class=\"kw-clinique\">Douloureux +++</span></td><td><span class=\"kw-clinique\">Peu douloureux</span></td></tr>\n          <tr><th>Palpation</th><td>—</td><td><span class=\"kw-clinique\">Induré</span></td><td><span class=\"kw-clinique\">Mou</span></td><td><span class=\"kw-clinique\">Mou</span></td><td>—</td></tr>\n          <tr><th>Fond</th><td><span class=\"kw-clinique\">Exsudat blanchâtre</span></td><td><span class=\"kw-clinique\">Propre, rosé</span></td><td>—</td><td><span class=\"kw-clinique\">Sale</span></td><td>—</td></tr>\n          <tr><th><span class=\"kw-clinique\">Adénopathie</span></th><td><span class=\"kw-clinique\">Sensibles</span></td><td><span class=\"kw-clinique\">Non inflammatoire</span></td><td><span class=\"kw-clinique\">Indolore</span></td><td><span class=\"kw-clinique\">Inflammatoire</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Étiologies non infectieuses :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Ulcération</span> <span class=\"kw-etio\">caustique</span>, <span class=\"kw-etio\">mécanique</span>, <span class=\"kw-etio\">physique</span></li>\n        <li><span class=\"kw-etio\">Aphtose génitale</span> (évoque une <span class=\"kw-def\">maladie de Behçet</span>, surtout si <span class=\"kw-clinique\">aphtose buccale</span> associée)</li>\n        <li><span class=\"kw-etio\">Carcinome</span></li>\n        <li>Localisations génitales de <span class=\"kw-etio\">toxidermie</span> (<span class=\"kw-alerte\">Lyell, Stevens-Johnson</span>), <span class=\"kw-etio\">dermatoses bulleuses</span>, <span class=\"kw-etio\">érythème polymorphe</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>CAT.</strong> <span class=\"kw-bio\">Sérologie syphilis systématique</span> devant toute <span class=\"kw-clinique\">ulcération</span> génitale. <strong>Ne pas attendre</strong> le résultat des TT/TNT pour traiter.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 115 — Toxidermies</em></p>","frequence":2},{"id":"162-6","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un herpès génital","contenu":"<p><strong>Herpès génital</strong> (<span class=\"kw-etio\">HSV2</span> dans 2/3 des cas, HSV1) : <span class=\"kw-clinique\">vésicules groupées en bouquet</span> (5-6) sur fond érythémateux, évoluant vers des <span class=\"kw-clinique\">ulcérations douloureuses</span> à <span class=\"kw-clinique\">fond exsudatif blanchâtre</span>, avec <span class=\"kw-clinique\">adénopathies sensibles</span>. Caractère <strong>douloureux</strong> = discriminant majeur <span class=\"kw-bio\">vs</span> la syphilis (indolore).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/162/herpes-genital.jpg\" alt=\"Herpès génital : vésicules groupées en bouquet évoluant vers des ulcérations douloureuses à fond blanchâtre\" loading=\"lazy\">\n        <figcaption>Herpès génital — vésicules groupées en bouquet (5-6) évoluant vers des ulcérations douloureuses. Source : à compléter.</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer herpes-genital.jpg dans assets/images/162/ -->","frequence":1},{"id":"162-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un chancre (syphilis primaire)","contenu":"<p><strong>Chancre syphilitique</strong> (point d'inoculation de <span class=\"kw-etio\">T. pallidum</span>, <span class=\"kw-alerte\">contagieux</span>) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Indolore</span> (≠ herpès et chancre mou)</li>\n        <li><span class=\"kw-clinique\">Unique</span> (parfois multiple, en miroir), <span class=\"kw-chiffre\">5–15 mm</span></li>\n        <li><span class=\"kw-clinique\">Fond propre, rosé</span> (≠ chancre mou à fond sale)</li>\n        <li><span class=\"kw-clinique\">Induré ++</span> = seul caractère vraiment évocateur</li>\n        <li><span class=\"kw-clinique\">Adénopathie satellite</span> inguinale, <span class=\"kw-clinique\">unilatérale</span>, <strong>non <span class=\"kw-etio\">inflammatoire</span></strong></li>\n      </ul>\n      <p>Localisation : <span class=\"kw-clinique\">sillon balano-préputial</span> (homme), partie externe de la <span class=\"kw-clinique\">vulve</span> (femme) ; possible anale, buccale, pharyngée.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/162/chancre-syphilis-primaire.jpg\" alt=\"Chancre syphilitique : ulcération unique indolore, indurée, à fond propre rosé du sillon balano-préputial\" loading=\"lazy\">\n        <figcaption>Chancre syphilitique primaire — <span class=\"kw-clinique\">ulcération</span> unique, indurée, indolore, fond propre rosé. Source : à compléter.</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer chancre-syphilis-primaire.jpg dans assets/images/162/ -->","frequence":1},{"id":"162-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques de l’urétrite masculine","contenu":"<p>L'<span class=\"kw-def\">urétrite masculine</span> associe écoulement et signes fonctionnels urétraux. Le tableau diffère selon le germe :</p>\n      <table >\n        <thead><tr><th></th><th>Gonocoque</th><th>Chlamydia</th></tr></thead>\n        <tbody>\n          <tr><th>Écoulement</th><td><span class=\"kw-clinique\">Purulent</span>, <span class=\"kw-clinique\">abondant</span> (<span class=\"kw-chiffre\">90 %</span>)</td><td><span class=\"kw-clinique\">Clair</span>, <span class=\"kw-clinique\">modéré</span>, <span class=\"kw-clinique\">intermittent</span> (<span class=\"kw-chiffre\">&lt; 50 %</span>)</td></tr>\n          <tr><th>Tableau</th><td>Bruyant ; <span class=\"kw-clinique\">brûlures mictionnelles</span>, <span class=\"kw-clinique\">dysurie</span>, <span class=\"kw-clinique\">prurit urétral</span>, <span class=\"kw-clinique\">méatite</span></td><td>Souvent peu bruyant, <span class=\"kw-clinique\">asymptomatique ≈ 50 %</span></td></tr>\n          <tr><th>Incubation</th><td>Courte (<span class=\"kw-chiffre\">2–7 j</span>)</td><td>Quelques jours à quelques mois</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Urétrite <span class=\"kw-ttt\">biologique</span>.</strong> Définie par <span class=\"kw-bio\">&gt; 5 PNN</span> au frottis urétral (grossissement 100) ou <span class=\"kw-bio\">&gt; 10 PNN</span> (grossissement 400).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 50 — Pathologie génito-scrotale chez le garçon et chez l'homme</em></p>","frequence":1},{"id":"162-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes des urétrites chez l’homme","contenu":"<p>Quatre germes principaux, dominés par les deux premiers :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Chlamydia trachomatis</span> — <strong>1ʳᵉ cause</strong> (<span class=\"kw-chiffre\">20–30 %</span> des urétrites en France)</li>\n        <li><span class=\"kw-etio\">Neisseria gonorrhoeae</span> (≈<span class=\"kw-chiffre\"> 10 %</span>)</li>\n        <li><span class=\"kw-etio\">Mycoplasma genitalium</span></li>\n        <li><span class=\"kw-etio\">Trichomonas vaginalis</span> (urétrite le plus souvent <span class=\"kw-clinique\">subaiguë</span>)</li>\n      </ul>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Gonocoque</th><th>Chlamydia</th></tr></thead>\n        <tbody>\n          <tr><th>Incubation</th><td>Courte (2–7 j)</td><td>Quelques jours à quelques mois</td></tr>\n          <tr><th>Écoulement</th><td><span class=\"kw-clinique\">Purulent</span> (<span class=\"kw-chiffre\">90 %</span>)</td><td><span class=\"kw-clinique\">Clair</span> (<span class=\"kw-chiffre\">40–50 %</span>)</td></tr>\n          <tr><th>Portage asymptomatique</th><td>Exceptionnel à l'urètre</td><td><strong>Très fréquent</strong> (≈<span class=\"kw-chiffre\"> 50 %</span> à l'urètre)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"162-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une infection génitale basse chez la femme","contenu":"<p>Les <span class=\"kw-def\">infections génitales basses</span> (IGB) = <span class=\"kw-def\">vaginite/vaginose</span> + <span class=\"kw-def\">cervicite</span>. L'orientation se fait sur les caractères des <span class=\"kw-clinique\">leucorrhées</span> :</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Leucorrhées</th><th>Signes locaux</th><th>Signes associés</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">Candida</span></th><td><span class=\"kw-clinique\">Blanches, caséeuses</span> (lait caillé)</td><td><span class=\"kw-clinique\">Prurit ++++</span></td><td><span class=\"kw-clinique\">Vulvite</span>, <span class=\"kw-clinique\">anite</span></td></tr>\n          <tr><th>Pyogènes</th><td><span class=\"kw-clinique\">Purulentes</span></td><td><span class=\"kw-clinique\">Brûlures</span></td><td>—</td></tr>\n          <tr><th><span class=\"kw-etio\">Trichomonas</span></th><td><span class=\"kw-clinique\">Vertes, spumeuses</span></td><td><span class=\"kw-clinique\">Prurit</span>, <span class=\"kw-clinique\">brûlures</span></td><td><span class=\"kw-clinique\">Urétrite</span>, <span class=\"kw-clinique\">odeur de moisi</span></td></tr>\n          <tr><th><span class=\"kw-etio\">Vaginose bactérienne</span></th><td><span class=\"kw-clinique\">Grisâtres</span>, peu abondantes</td><td>Rare <span class=\"kw-clinique\">prurit</span></td><td><span class=\"kw-clinique\">Odeur de poisson pourri</span> (sniff test)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cervicite</strong> (<span class=\"kw-etio\">gonocoque</span>, <span class=\"kw-etio\">Chlamydia</span>) : <span class=\"kw-clinique\">leucorrhées mucopurulentes</span>, <span class=\"kw-clinique\">fragilité du col</span>, <span class=\"kw-clinique\">ectropion friable hémorragique</span>. <span class=\"kw-etio\">Trichomonose</span> : <span class=\"kw-clinique\">colpite punctiforme</span> « framboisée » / « léopard » au spéculum.</p>","frequence":1},{"id":"162-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une infection génitale haute chez la femme (salpingite, endométrite)","contenu":"<p>Les <span class=\"kw-def\">IGH</span> (<span class=\"kw-def\">endométrite</span>, <span class=\"kw-def\">salpingite</span>) atteignent la <span class=\"kw-clinique\">femme jeune</span> ; nombreuses formes <strong><span class=\"kw-clinique\">pauci-symptomatiques</span> voire <span class=\"kw-clinique\">silencieuses</span></strong>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Terrain</span> / FdR</th><td><span class=\"kw-etio\">Femme jeune</span> ; <span class=\"kw-etio\">changement récent de partenaire</span> ; <span class=\"kw-etio\">urétrite du partenaire</span> ; <span class=\"kw-etio\">ATCD d'IST ou d'IGH</span> ; <span class=\"kw-etio\">gestes endo-utérins</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Fièvre</span></th><td>Souvent <span class=\"kw-clinique\">élevée</span> dans l'<span class=\"kw-clinique\">endométrite</span> ; <span class=\"kw-clinique\">inconstante</span> dans la <span class=\"kw-clinique\">salpingite</span></td></tr>\n          <tr><th>Signes fonctionnels</th><td><span class=\"kw-clinique\">Douleurs pelviennes</span> récentes, <span class=\"kw-clinique\">modérées</span>, <span class=\"kw-clinique\">progressives</span> ; <span class=\"kw-clinique\">dyspareunie profonde</span> ; <span class=\"kw-clinique\">leucorrhées anormales</span> ; <span class=\"kw-clinique\">métrorragies</span> (parfois) ; signes urinaires (<span class=\"kw-clinique\">pollakiurie</span>, <span class=\"kw-clinique\">brûlures mictionnelles</span>)</td></tr>\n          <tr><th>Spéculum</th><td><span class=\"kw-clinique\">Leucorrhées</span> abondantes, épaisses, jaunâtres/purulentes ; <span class=\"kw-clinique\">endocervicite</span> <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><th>Toucher vaginal ⭐</th><td><span class=\"kw-alerte\">Mobilisation utérine douloureuse</span> = <strong>signe le plus évocateur</strong> ; <span class=\"kw-clinique\">empâtement</span> / douleur des <span class=\"kw-clinique\">culs-de-sac latéraux</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège DIU.</strong> La <span class=\"kw-alerte\">pose de DIU</span> est un <span class=\"kw-etio\">FR transitoire</span> d'IGH, mais le <span class=\"kw-alerte\">port de DIU n'est PAS un FR</span> en lui-même.</div>\n      <div class=\"callout callout-warn\"><strong>Périhépatite (Fitz-Hugh-Curtis).</strong> <span class=\"kw-clinique\">Douleur de l'hypochondre droit</span> compliquant une IGH (<span class=\"kw-etio\">Chlamydia</span> <span class=\"kw-chiffre\">80 %</span>, <span class=\"kw-etio\">gonocoque</span> <span class=\"kw-chiffre\">20 %</span>), aspect en « <span class=\"kw-clinique\">cordes de violon</span> » en cœlioscopie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine</em></p>","frequence":4},{"id":"162-12","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes d’infections génitales basses chez la femme","contenu":"<p>Distinguer les causes <strong>IST</strong> des causes <strong>non-IST</strong> (déséquilibre de flore) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Germes</th></tr></thead>\n        <tbody>\n          <tr><th>IST</th><td><span class=\"kw-etio\">Trichomonas vaginalis</span> ; <span class=\"kw-etio\">gonocoque</span> ; <span class=\"kw-etio\">Chlamydia trachomatis</span> ; <span class=\"kw-etio\">Mycoplasma genitalium</span></td></tr>\n          <tr><th>NON-IST<br><em>(pas de contamination externe)</em></th><td><span class=\"kw-etio\">Candidose</span> (<em><span class=\"kw-etio\">Candida</span> albicans</em>) ; <span class=\"kw-etio\">vaginose bactérienne</span> (<em>Gardnerella vaginalis</em> / <em>M. hominis</em>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Candidose</span> et <span class=\"kw-clinique\">vaginose</span> sont des <strong>déséquilibres de la flore vaginale</strong> (perte des lactobacilles de Döderlein), pas des IST.</div>","frequence":0},{"id":"162-13","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes d’infections génitales hautes chez la femme","contenu":"<p>Les IGH résultent de l'<strong>ascension de germes</strong> du vagin/col vers l'utérus et les trompes (infections souvent <span class=\"kw-def\">polymicrobiennes</span>) :</p>\n      <ul>\n        <li><strong>IST</strong> (souvent secondaires à une IGB) : <span class=\"kw-etio\">Chlamydia trachomatis ++</span>, <span class=\"kw-etio\">gonocoque</span>, <span class=\"kw-etio\">Mycoplasma genitalium</span></li>\n        <li><strong>Manœuvre endo-utérine</strong> (hystéroscopie, <span class=\"kw-ttt\">curetage</span>, IVG, DIU) → germes de la flore : <span class=\"kw-etio\">streptocoques</span>, <span class=\"kw-etio\">staphylocoques</span>, <span class=\"kw-etio\">entérocoques</span>, <span class=\"kw-etio\">entérobactéries</span> (<em><span class=\"kw-etio\">E. coli</span> +++</em>, anaérobies, <em>Bacteroides fragilis</em>)</li>\n        <li><strong>Infection de voisinage</strong> (exceptionnel) : <span class=\"kw-etio\">appendicite</span>, <span class=\"kw-etio\">sigmoïdite</span></li>\n        <li><strong>Rare</strong> : <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">bilharziose</span></li>\n      </ul>","frequence":0},{"id":"162-14","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations extra génitales des IST","contenu":"<p>Les manifestations extra-génitales peuvent <strong>révéler le diagnostic</strong> :</p>\n      <table >\n        <thead><tr><th>Manifestation</th><th>Germes</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-clinique\">Rectite</span></th><td><span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-etio\">HSV1/2</span>, <span class=\"kw-etio\">gonocoque</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Conjonctivite</span> / <span class=\"kw-clinique\">ulcération</span> cornéenne</th><td><span class=\"kw-etio\">Gonocoque</span>, <span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-etio\">HSV</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Pharyngite</span></th><td><span class=\"kw-etio\">Gonocoque</span>, <span class=\"kw-etio\">HSV</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Périhépatite</span> (Fitz-Hugh-Curtis)</th><td><span class=\"kw-etio\">Chlamydia</span> (<span class=\"kw-chiffre\">80 %</span>), <span class=\"kw-etio\">gonocoque</span> (<span class=\"kw-chiffre\">20 %</span>)</td></tr>\n          <tr><th><span class=\"kw-clinique\">Érythème polymorphe</span></th><td><span class=\"kw-etio\">HSV</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Éruption pustuleuse</span> / <span class=\"kw-clinique\">arthrite septique</span></th><td><span class=\"kw-etio\">Gonocoque</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Arthrite réactionnelle</span></th><td><span class=\"kw-etio\">Chlamydia</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Recherche.</strong> Si <span class=\"kw-clinique\">pratiques sexuelles à risque</span> : <span class=\"kw-bio\">prélèvement multi-sites</span> (pharyngé, anal) pour rechercher un portage asymptomatique de gonocoque/Chlamydia.</div>","frequence":2},{"id":"162-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","contenu":"<p><strong>Bilan systématique pour toute IST</strong> (quel que soit le sexe et la manifestation) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Sérologies VIH, syphilis, VHB</span> ± <span class=\"kw-etio\">VHC</span> dans tous les cas</li>\n        <li>Si gonocoque, Chlamydia ou syphilis : <span class=\"kw-bio\">dépistage des 2 autres IST</span> (co-infections fréquentes)</li>\n        <li><span class=\"kw-alerte\">Déclaration anonyme à l'ARS</span> (importante) : <span class=\"kw-etio\">gonocoque</span> et <span class=\"kw-etio\">syphilis</span></li>\n      </ul>\n      <p><strong>Prélèvements orientés selon le tableau :</strong></p>\n      <ul>\n        <li><strong>Ulcérations génitales :</strong> prélèvements locaux + <span class=\"kw-bio\">sérologie</span></li>\n        <li><strong>Inflammation loco-régionale :</strong> écoulement urétral (1ʳᵉ intention), <span class=\"kw-bio\">1er jet urinaire</span> si pas d'écoulement ; chez la femme : prélèvement vaginal/cervical</li>\n        <li><strong>Manifestations extra-génitales :</strong> <span class=\"kw-bio\">hémocultures</span>, ponctions articulaires, prélèvement pharyngé, écouvillonnage anal</li>\n      </ul>\n      <p><strong>Diagnostic microbiologique par germe :</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Gonocoque :</span> examen direct (Gram), <span class=\"kw-bio\">culture (gélose chocolat)</span> + <span class=\"kw-bio\">PCR</span> (plus sensible)</li>\n        <li><span class=\"kw-etio\">Chlamydia :</span> <span class=\"kw-bio\">PCR/TAAN</span> — la <span class=\"kw-alerte\">sérologie est inutile</span></li>\n        <li><span class=\"kw-etio\">HSV :</span> <span class=\"kw-bio\">PCR</span> ; <span class=\"kw-etio\">Trichomonas :</span> <span class=\"kw-bio\">examen direct à l'état frais</span> + <span class=\"kw-bio\">PCR</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales</em></p>","frequence":2},{"id":"162-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mesures générales de prise en charge des IST (médicamenteuses et non médicamenteuses)","contenu":"<p><strong>Mesures non médicamenteuses :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Abstinence sexuelle</span> ou <span class=\"kw-clinique\">rapports protégés</span> jusqu'à fin de la contagiosité (<span class=\"kw-chiffre\">&gt; 7 jours</span>)</li>\n        <li><span class=\"kw-clinique\">Dépistage</span> + <span class=\"kw-ttt\">traitement des partenaires</span></li>\n        <li><span class=\"kw-clinique\">Éducation</span>, <span class=\"kw-clinique\">notification</span>, proposition de <span class=\"kw-ttt\">vaccinations</span></li>\n      </ul>\n      <p><strong>Mesures médicamenteuses :</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste ou documentée selon le germe</li>\n        <li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VIH</span> / <span class=\"kw-bio\">syphilis</span> / <span class=\"kw-bio\">VHB</span> systématiques ; <span class=\"kw-ttt\">PrEP</span> à envisager si risque répété</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Suivi</span>.</strong> <span class=\"kw-clinique\">Contrôle clinique</span> de guérison à <span class=\"kw-chiffre\">J7</span> ; <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">J3</span> si persistance des symptômes.</div>","frequence":1},{"id":"162-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les explorations à réaliser en cas d’infection génitale haute chez la femme","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr><th>Biologie</th><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> (éliminer une forme compliquée) ; <span class=\"kw-bio\">β-hCG</span> (GEU) ; <span class=\"kw-bio\">ECBU/BU</span> (PNA)</td></tr>\n          <tr><th>Microbiologie</th><td><span class=\"kw-bio\">PCR sur prélèvement vaginal</span> (IST) ; prélèvement endocervical (milieu Portagerm®) ; <span class=\"kw-bio\">mise en culture du DIU</span> retiré ; <span class=\"kw-bio\">sérologies</span> syphilis/<span class=\"kw-etio\">VIH</span>/VHB/VHC</td></tr>\n          <tr><th><span class=\"kw-imagerie\">Échographie pelvienne</span><br>(voie endovaginale ++)</th><td>Signes d'atteinte tubaire (<span class=\"kw-imagerie\">épaississement</span>, <span class=\"kw-imagerie\">aspect en roue dentée</span>) ; diagnostic d'un <span class=\"kw-imagerie\">abcès pelvien</span></td></tr>\n          <tr><th>Autres</th><td><span class=\"kw-imagerie\">TDM-AP / IRM</span> (éliminer autre cause) ; <span class=\"kw-bio\">biopsie endométriale</span> ; <span class=\"kw-imagerie\">cœlioscopie</span> (incertitude diagnostique ou échec du traitement)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Prélèvements (Collège).</strong> IGH non compliquée → prélèvement endocervical sous spéculum (examen direct + culture + <span class=\"kw-bio\">PCR</span>). IGH compliquée → prélèvements chirurgicaux/radioguidés (cœlioscopie ou <span class=\"kw-ttt\">ponction</span>).</div>","frequence":2},{"id":"162-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement probabiliste des IST","contenu":"<p>Le traitement probabiliste couvre <strong>toujours conjointement gonocoque + Chlamydia</strong> (co-infection fréquente) :</p>\n      <table >\n        <thead><tr><th>Situation</th><th><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</th></tr></thead>\n        <tbody>\n          <tr><th>IGB / urétrite-cervicite</th><td><span class=\"kw-ttt\">Ceftriaxone</span> IM dose unique (gonocoque)<br><span class=\"kw-ttt\">Doxycycline</span> PO <span class=\"kw-chiffre\">7 jours</span> (Chlamydia)</td></tr>\n          <tr><th>IGH</th><td><span class=\"kw-ttt\">Ceftriaxone</span> IM dose unique<br><span class=\"kw-ttt\">Doxycycline</span> PO <span class=\"kw-chiffre\">10 jours</span><br><span class=\"kw-ttt\">Métronidazole</span> PO <span class=\"kw-chiffre\">10 jours</span> (couvre les <span class=\"kw-etio\">anaérobies</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Gonocoque.</strong> 1ʳᵉ intention = <span class=\"kw-ttt\">ceftriaxone IM dose unique</span> ; les autres C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> ne sont pas validées. <span class=\"kw-ci\">Ciprofloxacine</span> <span class=\"kw-ci\">proscrite</span> en probabiliste (résistance &gt;<span class=\"kw-chiffre\"> 40 %</span>). Contrôle clinique à <span class=\"kw-chiffre\">J7</span>.</div>","frequence":1},{"id":"162-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de dépistage des infections à papillomavirus humain (HPV)","contenu":"<p><span class=\"kw-def\">Dépistage</span> des lésions induites par l'<span class=\"kw-etio\">HPV</span> (prévention du cancer du col) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Frottis cervico-utérin</span> entre <span class=\"kw-chiffre\">25 et 30 ans</span></li>\n        <li><span class=\"kw-bio\">Test HPV-HR</span> à partir de <span class=\"kw-chiffre\">30 ans</span> (toutes les femmes)</li>\n        <li><span class=\"kw-bio\">Examen proctologique</span> chez les <span class=\"kw-clinique\">HSH</span> et les femmes avec ATCD de dysplasie cervicale (surtout si <span class=\"kw-clinique\">VIH+</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Délai moyen infection persistante → cancer invasif du col ≈ <span class=\"kw-chiffre\">15 ans</span> : large fenêtre pour détecter et traiter les lésions précancéreuses.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeur col-corps utérin · 146 — Vaccination</em></p>","frequence":1},{"id":"162-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","contenu":"<table >\n        <thead><tr><th>Germe</th><th>Traitement documenté</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">Gonocoque</span></th><td>1. <span class=\"kw-ttt\">Ceftriaxone</span> IM dose unique (1ʳᵉ intention)<br>2. <span class=\"kw-ttt\">Gentamicine</span> IM DU si <span class=\"kw-ci\">allergie</span> aux C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span><br>3. <span class=\"kw-ci\">Ciprofloxacine</span> jamais en probabiliste (résistance &gt;<span class=\"kw-chiffre\"> 40 %</span>)</td></tr>\n          <tr><th><span class=\"kw-etio\">Chlamydia trachomatis</span></th><td><span class=\"kw-ttt\">Doxycycline</span> PO <span class=\"kw-chiffre\">7 jours</span> (<span class=\"kw-chiffre\">200 mg</span>/j)</td></tr>\n          <tr><th><span class=\"kw-etio\">Trichomonas vaginalis</span></th><td><span class=\"kw-ttt\">Métronidazole</span> PO (<span class=\"kw-chiffre\">2 g</span> DU ou 7-10 j) ou <span class=\"kw-ttt\">Secnidazole</span> (<span class=\"kw-chiffre\">2 g</span> DU) ; traiter le partenaire</td></tr>\n          <tr><th><span class=\"kw-etio\">Mycoplasma genitalium</span></th><td>Patients <strong>symptomatiques seulement</strong> : <span class=\"kw-ttt\">Doxycycline</span> 7 j puis <span class=\"kw-ttt\">Azithromycine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Règle d'or.</strong> Un traitement anti-<span class=\"kw-etio\">Chlamydia</span> est <strong>systématiquement associé</strong> au traitement du gonocoque.</div>","frequence":1},{"id":"162-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités thérapeutiques des infections génitales hautes de la femme","contenu":"<p><strong>IGH non compliquée — traitement externe</strong>, instauré sans attendre la microbiologie (durée 10-14 j) :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Ceftriaxone</span><span class=\"kw-chiffre\"> 1 g</span> IM dose unique (gonocoque, entérobactéries, strepto)</li>\n        <li><span class=\"kw-ttt\">Doxycycline</span><span class=\"kw-chiffre\"> 100 mg</span> ×<span class=\"kw-chiffre\">2/j</span> PO <span class=\"kw-chiffre\">10 jours</span> (Chlamydia)</li>\n        <li><span class=\"kw-ttt\">Métronidazole</span><span class=\"kw-chiffre\"> 500 mg</span> ×<span class=\"kw-chiffre\">2/j</span> PO <span class=\"kw-chiffre\">10 jours</span> (anaérobies)</li>\n      </ul>\n      <p><strong>Mesures associées :</strong> retrait du <span class=\"kw-clinique\">DIU</span>, repos, <span class=\"kw-ttt\">antalgiques</span>, préservatifs, traitement du partenaire, examen de contrôle.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>PEC</th></tr></thead>\n        <tbody>\n          <tr><th>IGH compliquée (<span class=\"kw-clinique\">abcès</span> pelvien, pelvipéritonite)</th><td><span class=\"kw-alerte\">Hospitalisation</span> + ATB parentérale <span class=\"kw-chiffre\">14-21 jours</span> ; <span class=\"kw-imagerie\">drainage</span> si <span class=\"kw-clinique\">abcès</span> &gt;<span class=\"kw-chiffre\"> 3-4 cm</span> ; <span class=\"kw-ttt\">chirurgie</span> si échec</td></tr>\n          <tr><th>Endométrite du post-partum ⚠️</th><td>Schéma différent : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span></td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"162-22","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prévention des IST","contenu":"<p>Prévention <strong>primaire</strong> et <strong>secondaire</strong> :</p>\n      <ul>\n        <li><strong>Primaire :</strong> <span class=\"kw-ttt\">préservatifs</span> M/F ; <span class=\"kw-ttt\">vaccinations</span> (<span class=\"kw-ttt\">HPV</span>, <span class=\"kw-ttt\">VHB</span>, <span class=\"kw-ttt\">VHA</span> chez les <span class=\"kw-clinique\">HSH</span>) ; <span class=\"kw-ttt\">PrEP</span> anti-<span class=\"kw-etio\">VIH</span> si prise de risque régulière ; <span class=\"kw-clinique\">éducation à la santé sexuelle</span></li>\n        <li><strong>Secondaire :</strong> <span class=\"kw-bio\">dépistage régulier</span> en cas d'expositions répétées ; <span class=\"kw-clinique\">notification</span> et <span class=\"kw-ttt\">traitement des partenaires</span> ; <span class=\"kw-bio\">dépistage des co-infections</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Vaccination <span class=\"kw-etio\">HPV</span>.</strong> Schéma à <span class=\"kw-chiffre\">2 doses</span> (<span class=\"kw-chiffre\">M0-M6</span>) entre <span class=\"kw-chiffre\">11 et 14 ans</span> (filles et garçons), rattrapage <span class=\"kw-chiffre\">15-19 ans</span> (<span class=\"kw-chiffre\">3 doses</span>), <span class=\"kw-clinique\">HSH</span> jusqu'à <span class=\"kw-chiffre\">26 ans</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales · 146 — Vaccination</em></p>","frequence":2},{"id":"162-23","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une syphilis précoce","contenu":"<p>La <span class=\"kw-def\">syphilis précoce</span> (&lt;<span class=\"kw-chiffre\"> 1 an</span>) regroupe la syphilis <span class=\"kw-def\">primaire</span>, <span class=\"kw-def\">secondaire</span> et latente précoce. Maladie due à <span class=\"kw-etio\">Treponema pallidum</span> (spirochète), <strong>très contagieuse</strong>, <strong>non immunisante</strong>.</p>\n      <p><strong>Syphilis primaire</strong> (incubation ≈ <span class=\"kw-chiffre\">3 semaines</span>) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Chancre</span> : <span class=\"kw-clinique\">indolore</span>, <span class=\"kw-clinique\">unique</span>, <span class=\"kw-chiffre\">5–15 mm</span>, <span class=\"kw-clinique\">induré</span>, <span class=\"kw-clinique\">fond propre rosé</span></li>\n        <li><span class=\"kw-clinique\">Adénopathie satellite</span> <span class=\"kw-clinique\">inguinale</span>, <span class=\"kw-clinique\">unilatérale</span>, <span class=\"kw-clinique\">non inflammatoire</span></li>\n      </ul>\n      <p><strong>Syphilis secondaire</strong> (débute ≈ <span class=\"kw-chiffre\">6 semaines</span> après le chancre, « <span class=\"kw-def\">grande simulatrice</span> ») :</p>\n      <table >\n        <thead><tr><th>Manifestation</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-clinique\">Roséole syphilitique</span></th><td><span class=\"kw-clinique\">Macules rose pâle</span> du <span class=\"kw-clinique\">tronc</span>, fugace (1ʳᵉ <span class=\"kw-clinique\">éruption</span>)</td></tr>\n          <tr><th><span class=\"kw-clinique\">Syphilides papuleuses</span></th><td><span class=\"kw-clinique\">Cuivrées</span> ; forme <span class=\"kw-clinique\">palmo-plantaire</span> (≈ <span class=\"kw-chiffre\">30 %</span>) très évocatrice</td></tr>\n          <tr><th><span class=\"kw-clinique\">Syphilides génitales</span></th><td><strong>Très contagieuses</strong> ; <span class=\"kw-clinique\">indolores</span>, <span class=\"kw-clinique\">multiples</span></td></tr>\n          <tr><th>Cutanéo-phanériens</th><td><span class=\"kw-clinique\">Fausse perlèche</span> ; <span class=\"kw-clinique\">alopécie en fourrure mitée</span> ; <span class=\"kw-clinique\">dépilation des sourcils</span></td></tr>\n          <tr><th>Signes généraux</th><td><span class=\"kw-clinique\">Fébricule</span> ; <span class=\"kw-clinique\">polyadénopathies</span> ; <span class=\"kw-clinique\">hépato-splénomégalie</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":3,"liens":[{"href":"https://fr.wikipedia.org/wiki/Signe_d%27Argyll_Robertson","label":"Wikipédia : signe d’Argyll-Robertson"}]},{"id":"162-24","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une syphilis tardive","contenu":"<p>La <span class=\"kw-def\">syphilis tardive</span> (&gt;<span class=\"kw-chiffre\"> 1 an</span> ou non datable) regroupe la syphilis <span class=\"kw-def\">tertiaire</span> et la syphilis latente tardive. Les tréponèmes sont rares (faible contagiosité) : les lésions sont liées à une réaction <span class=\"kw-def\">granulomateuse</span>.</p>\n      <p><strong>Syphilis tertiaire</strong> (rarissime) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Lésions vasculaires</span> : <span class=\"kw-clinique\">aortite syphilitique</span></li>\n        <li><span class=\"kw-clinique\">Lésions osseuses</span> : <span class=\"kw-clinique\">périostite</span></li>\n        <li>Lésions cutanéo-muqueuses nodulaires ulcérées : <span class=\"kw-clinique\">gommes</span></li>\n        <li>Manifestations neurologiques : <span class=\"kw-alerte\">tabès</span> (<span class=\"kw-clinique\">syndrome radiculo-cordonal postérieur</span>), <span class=\"kw-clinique\">démence</span></li>\n      </ul>\n      <p><strong>Neurosyphilis tardive :</strong> <span class=\"kw-clinique\">méningite chronique</span> ; <span class=\"kw-alerte\">tabès</span> (<span class=\"kw-clinique\">douleur</span>, <span class=\"kw-clinique\">ataxie</span>, <span class=\"kw-clinique\">aréflexie</span>) ; <span class=\"kw-clinique\">infarctus cérébraux</span> par angéite ; <span class=\"kw-alerte\">paralysie générale</span> (<span class=\"kw-clinique\">démence frontale</span> + <span class=\"kw-clinique\">mégalomanie</span>) ; <span class=\"kw-clinique\">signe d'Argyll-Robertson</span> (abolition du RPM, accommodation conservée).</p>","frequence":2},{"id":"162-25","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les différentes présentations cliniques de la syphilis secondaire (formes neurologiques notamment)","contenu":"<p>La syphilis secondaire (« <span class=\"kw-def\">grande simulatrice</span> ») évolue par <span class=\"kw-def\">floraisons</span> cutanéo-muqueuses entrecoupées de phases asymptomatiques :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Roséole syphilitique</span> (1ʳᵉ <span class=\"kw-clinique\">éruption</span>, macules rose pâle du tronc)</li>\n        <li><span class=\"kw-clinique\">Syphilides papuleuses</span> cuivrées et <span class=\"kw-clinique\">palmo-plantaires</span></li>\n        <li>Signes généraux : <span class=\"kw-clinique\">polyadénopathies</span>, fébricule, hépatite <span class=\"kw-ttt\">biologique</span></li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Neurosyphilis précoce 🚩.</strong>\n        <strong>Méningite aiguë</strong> (phase secondaire ou tertiaire)<br>\n        <strong>Atteinte ophtalmique :</strong> <span class=\"kw-alerte\">uvéite antérieure ++</span> ; uvéite postérieure, papillite, névrite optique<br>\n        <strong>Paires crâniennes :</strong> <span class=\"kw-clinique\">nerf auditif</span> (hypoacousie, acouphènes), oculomoteurs, facial<br>\n        <strong>CAT :</strong> <span class=\"kw-bio\">ponction lombaire</span> + <span class=\"kw-ttt\">pénicilline G IV 14 jours</span> quel que soit le <span class=\"kw-bio\">LCS</span></div>\n      <div class=\"callout callout-warn\"><strong>Piège QCM.</strong> Toute atteinte oculaire au cours d'une syphilis doit faire rechercher une <span class=\"kw-alerte\">neurosyphilis</span>.</div>","frequence":2},{"id":"162-26","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une éruption au stade de syphilis secondaire","contenu":"<p>Au <span class=\"kw-def\">stade</span> secondaire, deux éruptions sont à reconnaître :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Roséole syphilitique</span> : macules rose pâle, peu intenses, disséminées sur le <span class=\"kw-clinique\">tronc</span>, intervalles de peau saine</li>\n        <li><span class=\"kw-clinique\">Syphilides palmo-plantaires</span> : papules <span class=\"kw-clinique\">cuivrées</span> à cheval sur les plis palmaires — discrètes mais très évocatrices</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/162/syphilides-palmoplantaires.jpg\" alt=\"Syphilides palmo-plantaires : papules cuivrées sur les paumes au stade de syphilis secondaire\" loading=\"lazy\">\n        <figcaption>Syphilides palmo-plantaires cuivrées — <span class=\"kw-clinique\">éruption</span> évocatrice de syphilis secondaire. Source : à compléter.</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer syphilides-palmoplantaires.jpg dans assets/images/162/ -->","frequence":1},{"id":"162-27","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les tests sérologiques au cours de la syphilis","contenu":"<p>Le diagnostic de syphilis est <strong>sérologique</strong> (la culture est impossible). On distingue tests <span class=\"kw-def\">tréponémiques (TT)</span> et <span class=\"kw-def\">non tréponémiques (TNT)</span>.</p>\n      <table >\n        <thead><tr><th></th><th>TT (TPHA, ELISA, EIA, FTA)</th><th>TNT (VDRL, RPR)</th></tr></thead>\n        <tbody>\n          <tr><th>Spécificité</th><td>Des <strong>tréponématoses</strong> (pas de la syphilis seule)</td><td><span class=\"kw-alerte\">Non spécifique</span></td></tr>\n          <tr><th>Marqueur d'activité</th><td>Non (reste + après guérison)</td><td><strong>Oui</strong> (<span class=\"kw-def\">suivi</span> du traitement)</td></tr>\n          <tr><th>Positivation</th><td><span class=\"kw-chiffre\">7–10 j</span> après le chancre (<span class=\"kw-bio\">FTA</span> dès <span class=\"kw-chiffre\">5–8 j</span>)</td><td><span class=\"kw-chiffre\">10–15 j</span> après le chancre</td></tr>\n          <tr><th>En pratique</th><td><span class=\"kw-bio\">ELISA</span> en 1ʳᵉ intention</td><td><span class=\"kw-bio\">VDRL</span> si ELISA positif</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>FTA.</strong> Test tréponémique à <span class=\"kw-clinique\">positivation précoce</span> (<span class=\"kw-chiffre\">5–8 j</span>) : utile en cas de <span class=\"kw-clinique\">contage récent</span> avec <span class=\"kw-bio\">TPHA/VDRL négatifs</span> (<span class=\"kw-def\">syphilis primaire très précoce</span>). Inconvénient : nécessite un microscope à fluorescence (coûteux).</div>\n      <p><strong>Interprétation des 4 profils :</strong></p>\n      <table >\n        <thead><tr><th>Profil</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><th>TT− / TNT−</th><td>Absence de tréponématose, OU très récente (5-15 premiers jours — répéter à 1-2 sem), OU guérie traitée précocement</td></tr>\n          <tr><th>TT+ / TNT+</th><td>Tréponématose (traitée ou non, guérie ou non) — interprétation selon le titre du VDRL</td></tr>\n          <tr><th>TT− / TNT+</th><td><span class=\"kw-alerte\">Faux positif</span> (« fausse <span class=\"kw-bio\">sérologie</span> ») OU syphilis primaire (<span class=\"kw-chiffre\">10 %</span> : TNT+ avant TT)</td></tr>\n          <tr><th>TT+ / TNT−</th><td>Cicatrice sérologique (guérie), OU syphilis très précoce, OU tertiaire ancienne</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Faux positifs du VDRL.</strong> <span class=\"kw-etio\">Lupus</span>, <span class=\"kw-etio\">SAPL</span>, <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">VIH</span>, infections (lèpre, <span class=\"kw-etio\">tuberculose</span>, MNI, paludisme), toxicomanie IV, gammapathie.</div>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Suivi</span>.</strong> Traitement efficace si <span class=\"kw-bio\">VDRL divisé par 4</span> (2 dilutions) à <span class=\"kw-chiffre\">M6</span> ; guérison si VDRL négatif à <span class=\"kw-chiffre\">1 an</span> (précoce) ou <span class=\"kw-chiffre\">2 ans</span> (secondaire/tardive). Pas de résistance : une réascension = recontamination.</div>","frequence":5},{"id":"162-28","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de la syphilis primaire","contenu":"<p>Traitement de la syphilis <strong>précoce</strong> (dont la primaire) :</p>\n      <ul>\n        <li>1ʳᵉ intention : <span class=\"kw-ttt\">pénicilline G retard</span> (benzathine-benzylpénicilline) <span class=\"kw-chiffre\">2,4 MUI IM</span>, <strong>1 injection</strong></li>\n        <li>Si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">doxycycline</span> PO <span class=\"kw-chiffre\">14 jours</span></li>\n        <li>Devant une <span class=\"kw-clinique\">ulcération</span> génitale : <strong>traiter sans attendre la <span class=\"kw-bio\">sérologie</span></strong></li>\n        <li>Rechercher les autres IST, prendre en charge les partenaires</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Réaction de Jarisch-Herxheimer.</strong> <span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">céphalées</span>, myalgies dans les heures suivant l'ATB (lyse des tréponèmes) : <strong>bénigne</strong>, à ne pas confondre avec une <span class=\"kw-ci\">allergie</span> à la pénicilline.</div>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Suivi</span>.</strong> VDRL quantitatif ; guérison d'une syphilis primaire = <span class=\"kw-bio\">VDRL négatif à 1 an</span>.</div>","frequence":1,"liens":[{"href":"https://fr.wikipedia.org/wiki/R%C3%A9action_de_Jarisch-Herxheimer","label":"Wikipédia : réaction de Jarisch-Herxheimer"}]},{"id":"162-29","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de la syphilis secondaire","contenu":"<p>Le traitement dépend du <strong>temps écoulé</strong> (et de la présence d'une <span class=\"kw-alerte\">atteinte neurologique</span>), pas du <span class=\"kw-def\">stade</span> clinique. La <span class=\"kw-clinique\">syphilis secondaire</span> reste une <strong>forme précoce</strong> (<span class=\"kw-chiffre\">&lt; 1 an</span>).</p>\n      <table >\n        <thead><tr><th>Forme</th><th>1ʳᵉ intention</th><th>Si <span class=\"kw-ci\">allergie</span></th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-clinique\">Précoce</span> (<span class=\"kw-chiffre\">&lt; 1 an</span>)<br><em>= secondaire</em></th><td><span class=\"kw-ttt\">Pénicilline G retard</span> <span class=\"kw-chiffre\">2,4 MUI IM</span> — <strong>1 injection</strong></td><td><span class=\"kw-ttt\">Doxycycline</span> <span class=\"kw-chiffre\">14 j</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Tardive</span> (<span class=\"kw-chiffre\">&gt; 1 an</span>)</th><td><span class=\"kw-ttt\">Pénicilline G retard</span> — <strong>3 injections IM</strong> à <span class=\"kw-chiffre\">8 j</span> d'intervalle</td><td><span class=\"kw-ttt\">Doxycycline</span> <span class=\"kw-chiffre\">14 j</span></td></tr>\n          <tr><th><span class=\"kw-alerte\">Neurosyphilis</span></th><td><span class=\"kw-ttt\">Pénicilline G non retard IV</span> <span class=\"kw-chiffre\">14 jours</span> (2-3 sem)</td><td><span class=\"kw-alerte\">Désensibilisation</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ci\">Allergie</span> + situation à risque.</strong> Femme enceinte, <span class=\"kw-etio\">VIH</span> ou neurosyphilis : la <span class=\"kw-alerte\">désensibilisation</span> à la pénicilline est recommandée (la <span class=\"kw-ci\">doxycycline</span> est <span class=\"kw-ci\">contre-indiquée</span> chez la femme enceinte).</div>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Suivi</span>.</strong> Contrôle clinique + VDRL à <span class=\"kw-chiffre\">M3</span> et <span class=\"kw-chiffre\">M6</span> ; guérison d'une syphilis secondaire = <span class=\"kw-bio\">VDRL négatif à 2 ans</span>.</div>","frequence":5},{"id":"162-30","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques liées au HPV","contenu":"<p>L'<span class=\"kw-etio\">HPV</span> a un tropisme pour les <span class=\"kw-def\">épithéliums malpighiens</span>. ≈<span class=\"kw-chiffre\"> 80 %</span> des personnes font <span class=\"kw-chiffre\">≥ 1</span> infection au cours de leur vie ; élimination spontanée dans <span class=\"kw-chiffre\">90 %</span> des cas en <span class=\"kw-chiffre\">1-2 ans</span>.</p>\n      <p><strong>Lésions muqueuses (anogénitales) :</strong></p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Caractéristiques</th><th><span class=\"kw-etio\">HPV</span></th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-clinique\">Condylomes acuminés</span></th><td>« crêtes-de-coq » : <span class=\"kw-clinique\">masses charnues</span> à <span class=\"kw-clinique\">verrucosités kératosiques</span></td><td><span class=\"kw-etio\">6 et 11</span> (<span class=\"kw-chiffre\">90 %</span>)</td></tr>\n          <tr><th><span class=\"kw-clinique\">Condylomes plans</span></th><td><span class=\"kw-clinique\">Macules-papules rosées</span>, visibles après <span class=\"kw-bio\">acide acétique</span></td><td><span class=\"kw-etio\">6 et 11</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Néoplasies intra-épithéliales</span></th><td>Cervicales, vulvaires, anales, péniennes : <span class=\"kw-alerte\">lésions précancéreuses</span></td><td><span class=\"kw-etio\">HR (16/18…)</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Papulose bowénoïde</span></th><td><span class=\"kw-alerte\">Dysplasie sévère</span> de l'adulte jeune</td><td><span class=\"kw-etio\">16/18</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Lésions cutanées bénignes (verrues) :</strong> <span class=\"kw-clinique\">myrmécie</span> (<span class=\"kw-etio\">HPV1</span>), <span class=\"kw-clinique\">mosaïque</span> (<span class=\"kw-etio\">HPV2</span>), <span class=\"kw-clinique\">verrues vulgaires</span> (<span class=\"kw-etio\">HPV2</span>), <span class=\"kw-clinique\">verrues planes</span> (<span class=\"kw-etio\">HPV3</span>).</p>\n      <div class=\"callout callout-warn\"><strong>Oncogénicité.</strong> <span class=\"kw-etio\">HPV 16 et 18</span> = principaux génotypes oncogènes (col, vulve, vagin, anus, ORL). <span class=\"kw-etio\">HPV</span> 6/11 = condylomes (non oncogènes).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeur col-corps utérin</em></p>","frequence":0},{"id":"162-31","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de traitement des infections liées au HPV","contenu":"<p><strong>Pas de traitement <span class=\"kw-ttt\">antiviral</span> spécifique</strong> : l'objectif est la disparition des lésions visibles (le virus peut persister → <span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">M6</span>).</p>\n      <table >\n        <thead><tr><th>Méthode</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><th>Destruction physique</th><td><span class=\"kw-ttt\">Laser CO2</span> ; <span class=\"kw-ttt\">électrocoagulation</span> ; <span class=\"kw-ttt\">cryothérapie</span> (<span class=\"kw-clinique\">azote liquide</span>, douloureuse)</td></tr>\n          <tr><th>Destruction chimique</th><td><span class=\"kw-ttt\">Podophyllotoxine</span> <span class=\"kw-chiffre\">0,5 %</span> (auto-application) — <span class=\"kw-ci\">CI grossesse et enfant</span></td></tr>\n          <tr><th>Destruction immunologique</th><td><span class=\"kw-ttt\">Imiquimod</span> topique (<span class=\"kw-chiffre\">3×/sem</span>, <span class=\"kw-chiffre\">16 sem</span>)</td></tr>\n          <tr><th>Verrues cutanées</th><td><span class=\"kw-ttt\">Kératolytiques</span> (<span class=\"kw-ttt\">acide salicylique</span>) ; <span class=\"kw-ttt\">cryothérapie</span> ; <span class=\"kw-ttt\">laser CO2</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Prévention associée.</strong> <span class=\"kw-ttt\">Vaccination HPV</span> (Gardasil9® nonavalent : 6/11/16/18/31/33/45/52/58) ; <span class=\"kw-def\">dépistage</span> des autres IST ; dépistage du partenaire si condylomes ; <span class=\"kw-def\">suivi</span> cervical (<span class=\"kw-bio\">frottis / test HPV-HR</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeur col-corps utérin · 146 — Vaccination</em></p>","frequence":0},{"id":"162-32","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies parasitaires des IST","contenu":"<p>Trois agents parasitaires transmissibles sexuellement :</p>\n      <ul>\n        <li><strong>Protozoaire :</strong> <span class=\"kw-etio\">Trichomonas vaginalis</span> (flagellé anaérobie) — surtout responsable de <span class=\"kw-clinique\">cervico-vaginite</span> (<span class=\"kw-clinique\">leucorrhées vertes spumeuses</span>, <span class=\"kw-clinique\">odeur de moisi</span>)</li>\n        <li><strong>Ectoparasite :</strong> <span class=\"kw-etio\">gale</span> (<span class=\"kw-etio\">Sarcoptes scabiei var. hominis</span>) — <span class=\"kw-clinique\">prurit</span> à recrudescence nocturne</li>\n        <li><strong>Insecte hématophage :</strong> <span class=\"kw-etio\">phtirose pubienne</span> (<span class=\"kw-etio\">Phtirus pubis</span>, pou du pubis ou « <span class=\"kw-clinique\">morpion</span> »)</li>\n      </ul>","frequence":0},{"id":"162-33","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les examens complémentaires à réaliser pour le diagnostic d’une trichomonose, d’une infection à Chlamydia trachomatis et Neisseria gonorrheae","contenu":"<table >\n        <thead><tr><th>Germe</th><th>Prélèvement</th><th>Analyse</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">Trichomonas vaginalis</span></th><td>Cul-de-sac vaginal postérieur (femme), urètre antérieur (homme)</td><td><span class=\"kw-bio\">Examen direct à l'état frais</span> (parasite mobile) + <span class=\"kw-bio\">PCR</span> (pas de culture)</td></tr>\n          <tr><th><span class=\"kw-etio\">Chlamydia trachomatis</span></th><td>1er jet urinaire (homme) ; auto-écouvillonnage vaginal (femme)</td><td><span class=\"kw-bio\">PCR/TAAN</span> (plus sensible que la culture) — <span class=\"kw-alerte\">sérologie inutile</span></td></tr>\n          <tr><th><span class=\"kw-etio\">Neisseria gonorrhoeae</span></th><td>1er jet urinaire / écoulement ; ± pharyngé, anal</td><td><span class=\"kw-bio\">PCR biplex</span> ; <span class=\"kw-bio\">examen direct (Gram)</span> = diplocoques intracellulaires ; <span class=\"kw-bio\">culture (gélose chocolat)</span> + <span class=\"kw-bio\">antibiogramme</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-bio\">PCR</span> Chlamydia + gonocoque souvent réalisée en <span class=\"kw-bio\">biplex</span>. La <span class=\"kw-bio\">culture du gonocoque</span> reste indispensable pour l'<span class=\"kw-bio\">antibiogramme</span> (<span class=\"kw-def\">suivi</span> des résistances).</div>","frequence":1},{"id":"162-34","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement d’une trichomonose, d’une infection à Chlamydia trachomatis et Neisseria gonorrheae","contenu":"<table >\n        <thead><tr><th>Germe</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-etio\">Trichomonas</span></th><td><span class=\"kw-ttt\">Métronidazole</span> PO (<span class=\"kw-chiffre\">2 g</span> DU ou 7-10 j) ou <span class=\"kw-ttt\">Secnidazole</span> (<span class=\"kw-chiffre\">2 g</span> DU) ; <strong>traiter le partenaire</strong></td></tr>\n          <tr><th><span class=\"kw-etio\">Chlamydia</span></th><td><span class=\"kw-ttt\">Doxycycline</span> PO <span class=\"kw-chiffre\">7 jours</span> (1ʳᵉ intention) ; femme enceinte : <span class=\"kw-ttt\">azithromycine</span><span class=\"kw-chiffre\"> 1 g</span> DU</td></tr>\n          <tr><th><span class=\"kw-etio\">Gonocoque</span></th><td><span class=\"kw-ttt\">Ceftriaxone</span><span class=\"kw-chiffre\"> 1 g</span> IM dose unique + <strong>anti-Chlamydia systématique</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Co-traitement.</strong> Devant un gonocoque, toujours associer un traitement anti-<span class=\"kw-etio\">Chlamydia</span> (<span class=\"kw-ttt\">doxycycline</span> 7 j à privilégier).</div>","frequence":0},{"id":"162-35","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales conséquences à long terme des IGH chez la femme","contenu":"<p>Les <span class=\"kw-def\">IGH</span> exposent à des <strong>séquelles tubaires définitives</strong>, même en cas de forme non compliquée (phénomènes immuno-inflammatoires) :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Stérilité tubaire</span> (<span class=\"kw-etio\">Chlamydia</span> = ≈ <span class=\"kw-chiffre\">70 %</span> des stérilités tubaires)</li>\n        <li><span class=\"kw-alerte\">Grossesse extra-utérine (GEU)</span></li>\n        <li><span class=\"kw-alerte\">Douleurs pelviennes chroniques</span> (<span class=\"kw-clinique\">syndrome adhérentiel</span>)</li>\n        <li>Risque de <span class=\"kw-clinique\">récidive majoré</span> après un 1ᵉʳ épisode</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> Le pronostic des IST est à la fois <strong>fonctionnel</strong> (stérilité, surtout chez la femme) et parfois <strong>vital</strong> (<span class=\"kw-etio\">VIH</span>, exceptionnellement gonococcémie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine</em></p>","frequence":0},{"id":"162-36","rang":"B","rubrique":"Diagnostic positif","titre":"Reconnaitre les particularités des IST en fonction de l’âge","contenu":"<table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-clinique\">Femme jeune</span> (<span class=\"kw-chiffre\">&lt; 25 ans</span>)</th><td>Essentiellement <span class=\"kw-etio\">Chlamydia trachomatis</span> et <span class=\"kw-etio\">HSV</span> ; étiologies rarissimes chez la ménopausée</td></tr>\n          <tr><th>Femme ménopausée</th><td><span class=\"kw-clinique\">Leucorrhées</span> : <span class=\"kw-clinique\">atrophie</span> (<span class=\"kw-clinique\">vaginite sénile</span>, carence hormonale) ; rechercher une <span class=\"kw-alerte\">origine néoplasique</span> cervicale/endométriale</td></tr>\n          <tr><th>Jeune fille</th><td><span class=\"kw-clinique\">Vulvovaginites infectieuses</span> (<span class=\"kw-etio\">S. pyogenes</span>, <span class=\"kw-etio\">oxyurose</span>, <span class=\"kw-etio\">mycose</span>) ; <span class=\"kw-clinique\">corps étranger intravaginal</span></td></tr>\n          <tr><th>Enfant (<span class=\"kw-etio\">HPV</span>/condylome)</th><td>Contamination mère-enfant ou manuportée ; <strong>mauvais marqueur de sévices sexuels</strong> mais rester vigilant</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"162-37","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un condylome","contenu":"<p>Deux formes de <span class=\"kw-clinique\">condylomes</span> à <span class=\"kw-etio\">HPV</span> (6/11) à reconnaître :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Condylomes acuminés</span> (« crêtes-de-coq ») : masses charnues hérissées de petites verrucosités kératosiques de <span class=\"kw-chiffre\">0,2 à 1 cm</span></li>\n        <li><span class=\"kw-clinique\">Condylomes plans</span> : macules-papules rosées, isolées ou en nappes, mieux visibles après <span class=\"kw-bio\">acide acétique</span></li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/162/condylome-acumine.jpg\" alt=\"Condylome acuminé anogénital en crête-de-coq, masse charnue à verrucosités kératosiques\" loading=\"lazy\">\n        <figcaption>Condylome acuminé « crête-de-coq » — verrue anogénitale à <span class=\"kw-etio\">HPV</span> 6/11. Source : à compléter.</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer condylome-acumine.jpg dans assets/images/162/ -->","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>IST :</strong> rarement une <span class=\"kw-alerte\">urgence</span> vitale, mais quelques situations imposent une PEC immédiate.<br><strong>Atteinte oculaire/neurologique syphilitique :</strong> <span class=\"kw-alerte\">neurosyphilis précoce</span> → <span class=\"kw-ttt\">ponction lombaire</span> + <span class=\"kw-ttt\">pénicilline G IV 14 jours</span><br><strong>Septicémie gonococcique :</strong> <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">ceftriaxone IV</span><br><strong>IGH compliquée :</strong> <span class=\"kw-alerte\">abcès tubo-ovarien</span> ou <span class=\"kw-alerte\">pelvipéritonite</span> → <span class=\"kw-alerte\">hospitalisation</span><br><strong><span class=\"kw-clinique\">Ulcération</span> génitale :</strong> traiter <span class=\"kw-alerte\">sans attendre</span> le résultat des TT/TNT</p>","hospit":"<p><strong>Ambulatoire (majorité des cas) :</strong> urétrite, cervicite, IGB, IGH non compliquée, syphilis, condylomes<br><strong>Traitement minute :</strong> dose unique délivrée sur le <span class=\"kw-ttt\">lieu de la consultation</span><br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-etio\">IGH compliquée</span> (<span class=\"kw-clinique\">abcès</span> pelvien, pelvipéritonite), <span class=\"kw-etio\">septicémie</span>, <span class=\"kw-etio\">endocardite</span> ou <span class=\"kw-etio\">méningite à gonocoque</span><br><strong>Avis spécialisé :</strong> <span class=\"kw-etio\">neurosyphilis</span> ; <span class=\"kw-etio\">syphilis de la femme enceinte</span> <span class=\"kw-etio\">allergique</span> à la pénicilline</p>","redflags":"<ul><li><span class=\"kw-alerte\">Ulcération génitale</span> : augmente la transmission sexuelle du <span class=\"kw-etio\">VIH</span></li><li><span class=\"kw-alerte\">Atteinte oculaire</span> (<span class=\"kw-clinique\">uvéite antérieure</span>) ou neurologique au cours de la syphilis = <span class=\"kw-etio\">neurosyphilis précoce</span></li><li><span class=\"kw-alerte\">AEG, fièvre élevée, frissons</span> chez une femme avec douleurs pelviennes (IGH compliquée)</li><li><span class=\"kw-alerte\">Défense abdominale</span> ou <span class=\"kw-clinique\">masse</span> pelvienne fixée au toucher vaginal</li><li><span class=\"kw-alerte\">Septicémie gonococcique</span> : <span class=\"kw-clinique\">purpura pétéchial</span>, <span class=\"kw-clinique\">arthrites septiques</span>, papulo-pustules acrales</li><li><span class=\"kw-bio\">CRP fréquemment > 100 mg/L</span> avec hyperleucocytose (<span class=\"kw-clinique\">abcès</span> pelvien)</li></ul>","principes":"<p>PEC probabiliste précoce, sans attendre les résultats, + mesures associées systématiques (partenaires, <span class=\"kw-def\">dépistage</span>, prévention).</p><p><strong>Urétrite / cervicite / IGB (probabiliste)</strong></p><p>Toujours couvrir gonocoque ET Chlamydia (co-infection fréquente)</p><ul><li><span class=\"kw-ttt\">Ceftriaxone IM dose unique</span> (gonocoque)</li><li>+ <span class=\"kw-ttt\">Doxycycline 7 jours PO</span> (Chlamydia)</li><li><span class=\"kw-chiffre\">2e intention</span> si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">gentamicine IM dose unique</span></li><li><span class=\"kw-ci\">Ciprofloxacine non recommandée en probabiliste (résistance > 40 %)</span></li></ul><p><strong>IGH non compliquée (ambulatoire)</strong></p><p>Traitement instauré sans attendre les résultats microbiologiques</p><ul><li><span class=\"kw-ttt\">Ceftriaxone IM dose unique</span></li><li>+ <span class=\"kw-ttt\">Doxycycline 10 jours</span></li><li>+ <span class=\"kw-ttt\">Métronidazole 10 jours</span> (anaérobies)</li><li>Retrait du <span class=\"kw-ttt\">DIU</span>, repos, <span class=\"kw-ttt\">antalgiques</span></li></ul><p><strong>Syphilis (selon la temporalité)</strong></p><p>La <span class=\"kw-def\">classification</span> selon le temps écoulé conditionne le traitement</p><ul><li><span class=\"kw-etio\">Précoce (< 1 an)</span> : <span class=\"kw-ttt\">pénicilline G retard, 1 injection IM</span></li><li><span class=\"kw-etio\">Tardive (> 1 an)</span> : <span class=\"kw-ttt\">pénicilline G retard, 3 injections IM à 1 semaine d'intervalle</span></li><li><span class=\"kw-etio\">Neurosyphilis</span> : <span class=\"kw-ttt\">pénicilline G non retard IV 14 jours</span></li><li>Si allergie : <span class=\"kw-ttt\">doxycycline 14 jours</span> (désensibilisation si grossesse/VIH/neurosyphilis)</li></ul><p><strong>Mesures associées (toute IST)</strong></p><ul><li><span class=\"kw-ttt\">Dépistage et traitement des partenaires</span> (d'emblée pour Chlamydia et syphilis si dernier rapport < 6 semaines)</li><li><span class=\"kw-bio\">Sérologies VIH, syphilis, VHB</span> systématiques</li><li>Dépistage des co-infections (gonocoque / Chlamydia / syphilis)</li><li>Abstinence ou préservatif pendant <span class=\"kw-chiffre\">7 jours</span></li><li><span class=\"kw-ttt\">Vaccination HPV, VHB, VHA</span> (à proposer aux HSH)</li></ul><p><strong>Prévention HPV</strong></p><ul><li><span class=\"kw-ttt\">Vaccin nonavalent</span> à<span class=\"kw-chiffre\"> 11-14 ans</span> (<span class=\"kw-chiffre\">M0, M6</span>), rattrapage <span class=\"kw-chiffre\">15-19 ans</span> (<span class=\"kw-chiffre\">M0, M2, M6</span>)</li><li><span class=\"kw-bio\">Frottis cervical</span><span class=\"kw-chiffre\"> 25-30 ans</span> puis <span class=\"kw-bio\">test HPV-HR</span> à partir de <span class=\"kw-chiffre\">30 ans</span></li></ul>","suivi":"<p><strong>Contrôle clinique systématique :</strong> à <span class=\"kw-chiffre\">J7</span> (guérison, tolérance, <span class=\"kw-bio\">antibiogramme</span>) ; à <span class=\"kw-chiffre\">J3</span> si persistance des symptômes<br><strong>Gonocoque :</strong> contrôle bactériologique à <span class=\"kw-chiffre\">J7</span> si signes persistants ; contrôle <span class=\"kw-bio\">PCR à 15 jours</span> dans les formes asymptomatiques<br><strong>Chlamydia :</strong> contrôle <span class=\"kw-bio\">PCR</span> non précoce, à <span class=\"kw-chiffre\">M3-M6</span> chez les patients à haut risque de réinfection<br><strong>Syphilis :</strong> <span class=\"kw-def\">suivi</span> sur le <span class=\"kw-bio\">VDRL quantitatif</span> — efficace si titre divisé par 4 à <span class=\"kw-chiffre\">M6</span> ; guérison si <span class=\"kw-bio\">VDRL négatif à 1 an</span> (précoce) ou <span class=\"kw-bio\">à 2 ans</span> (tardive) ; réascension = recontamination</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-162.pdf","label":"Pilly étudiant 2023 — item 162 (IST)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion d'IST — Orientation selon le tableau clinique dominant","detail":"<h4>CAT — Suspicion d'IST selon le tableau clinique — Orientation diagnostique et traitement probabiliste</h4>","branches":[{"to":"q-ulcere","label":"Analyser le tableau clinique","color":"blue"}]},{"id":"q-ulcere","kind":"decision","label":"Ulcération génitale, anale ou buccopharyngée ?","branches":[{"to":"t-ulcere","label":"Oui","color":"amber"},{"to":"q-ecoul","label":"Non","color":"blue"}]},{"id":"t-ulcere","kind":"terminal","label":"Sérologie syphilis + traitement sans attendre — Toute ulcération = syphilis jusqu'à preuve du contraire","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Sérologie syphilis systématique</span> (TT type <span class=\"kw-bio\">ELISA</span>)</li><li><span class=\"kw-bio\">PCR</span> locale : <span class=\"kw-etio\">HSV</span>, <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-etio\">Chlamydia génotype L (LGV)</span></li><li>Bilan IST : <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">VIH</span>, <span class=\"kw-bio\">VHB</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Ne pas attendre</span> le résultat des TT/TNT pour traiter</li><li>Syphilis précoce : <span class=\"kw-ttt\">pénicilline G retard, 1 injection IM</span></li><li>Herpès (primo-infection) : <span class=\"kw-ttt\">valaciclovir 10 jours</span></li></ul>"},{"id":"q-ecoul","kind":"decision","label":"Écoulement ou signes d'urétrite / de cervicite ?","branches":[{"to":"t-igb","label":"Oui","color":"green"},{"to":"q-pelv","label":"Non","color":"blue"}]},{"id":"t-igb","kind":"terminal","label":"Traitement probabiliste minute (ambulatoire) — Couvrir systématiquement gonocoque + Chlamydia","color":"green","detail":"<h4>Paraclinique</h4><ul><li>Prélèvement sur <span class=\"kw-bio\">écoulement urétral</span> (1re intention) ou <span class=\"kw-bio\">1er jet d'urine</span></li><li><span class=\"kw-bio\">PCR biplex</span> gonocoque + Chlamydia</li><li><span class=\"kw-bio\">Culture sur gélose au sang cuit</span> (<span class=\"kw-bio\">antibiogramme</span> du gonocoque)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ceftriaxone IM dose unique</span> (gonocoque)</li><li>+ <span class=\"kw-ttt\">Doxycycline 7 jours PO</span> (Chlamydia)</li><li><span class=\"kw-ci\">Ciprofloxacine évitée (résistance > 40 %)</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-chiffre\">Contrôle clinique systématique à J7</span></li><li><span class=\"kw-ttt\">Traitement des partenaires</span>, abstinence/préservatif <span class=\"kw-chiffre\">7 jours</span></li></ul>"},{"id":"q-pelv","kind":"decision","label":"Douleurs pelviennes + mobilisation utérine douloureuse (femme) ?","branches":[{"to":"q-grav","label":"Oui","color":"amber"},{"to":"t-extra","label":"Non","color":"blue"}]},{"id":"q-grav","kind":"decision","label":"Signes de gravité ou de complication ? — AEG, fièvre élevée, défense, masse pelvienne, sepsis","branches":[{"to":"t-igh-comp","label":"Signes de gravité","color":"red"},{"to":"t-igh-nc","label":"Absence de gravité","color":"amber"}]},{"id":"t-igh-comp","kind":"terminal","label":"Hospitalisation — IGH compliquée — Abcès tubo-ovarien, pelvipéritonite, sepsis","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">AEG, fièvre, frissons</span></li><li><span class=\"kw-alerte\">Défense abdominale</span>, <span class=\"kw-clinique\">masse</span> pelvienne latéro-utérine au <span class=\"kw-alerte\">TV</span></li><li><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">inflammatoire</span></span> marqué (<span class=\"kw-bio\">CRP > 100 mg/L</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie pelvienne</span> : <span class=\"kw-radio\">collection liquidienne</span></li><li><span class=\"kw-imagerie\">TDM-AP</span> (pelvipéritonite, élimine une origine extra-génitale)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">ATB parentérale 14-21 jours</span> : <span class=\"kw-ttt\">ceftriaxone</span> + <span class=\"kw-ttt\">métronidazole</span> + <span class=\"kw-ttt\">doxycycline</span></li><li><span class=\"kw-ttt\">Drainage</span> si collection <span class=\"kw-chiffre\">> 3-4 cm</span> (<span class=\"kw-ttt\">ponction</span> échoguidée ou cœlioscopie)</li><li>Adjonction de <span class=\"kw-ttt\">gentamicine</span> si <span class=\"kw-alerte\">sepsis sévère</span></li></ul>"},{"id":"t-igh-nc","kind":"terminal","label":"IGH non compliquée — traitement ambulatoire — Sans attendre les résultats microbiologiques","color":"amber","detail":"<h4>Paraclinique</h4><ul><li>Éliminer une forme compliquée : <span class=\"kw-bio\">NFS, CRP</span></li><li>Éliminer une GEU : <span class=\"kw-bio\">β-hCG</span> ; une PNA : <span class=\"kw-bio\">ECBU</span></li><li><span class=\"kw-imagerie\">Échographie pelvienne endovaginale</span> (recherche d'<span class=\"kw-clinique\">abcès</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ceftriaxone IM dose unique</span></li><li>+ <span class=\"kw-ttt\">Doxycycline 10 jours</span> + <span class=\"kw-ttt\">Métronidazole 10 jours</span></li><li>Retrait DIU, <span class=\"kw-ttt\">antalgiques</span>, traitement du partenaire</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Examen clinique de contrôle</li><li>Risque à long terme : <span class=\"kw-etio\">GEU</span>, <span class=\"kw-etio\">stérilité tubaire</span>, <span class=\"kw-etio\">douleurs pelviennes chroniques</span></li></ul>"},{"id":"t-extra","kind":"terminal","label":"Manifestation extra-génitale ou bilan de dépistage — Une atteinte extra-génitale peut révéler l'IST","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Rectite</span>, <span class=\"kw-clinique\">conjonctivite</span>, <span class=\"kw-clinique\">pharyngite</span></li><li><span class=\"kw-clinique\">Arthrite</span> (septique = gonocoque ; réactionnelle = Chlamydia)</li><li><span class=\"kw-clinique\">Péri-hépatite (Fitz-Hugh-Curtis)</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Prélèvement multi-sites</span> (pharyngé, anal) si pratiques à risque</li><li>Bilan IST : <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">VIH, syphilis, VHB</span></li><li><span class=\"kw-bio\">PCR</span> gonocoque + Chlamydia</li></ul>"}]},"cards":[{"i":"4b5a83a42947","n":162,"o":"162-10","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une infection génitale basse chez la femme","q":"Comment les leucorrhées peuvent-elles orienter vers une étiologie spécifique lors d'une infection génitale basse chez la femme ?","a":"<p>L'aspect des leucorrhées est un élément clé d'orientation :</p><ul><li>Des leucorrhées <strong>blanches, caséeuses</strong> (aspect de lait caillé) sont évocatrices d'une infection à <strong>Candida</strong>.</li><li>Des leucorrhées <strong>purulentes</strong> suggèrent des germes <strong>pyogènes</strong>.</li><li>Des leucorrhées <strong>vertes, spumeuses</strong> sont caractéristiques d'une infection à <strong>Trichomonas</strong>.</li><li>Des leucorrhées <strong>grisâtres, peu abondantes</strong> orientent vers une <strong>vaginose bactérienne</strong>.</li><li>Des leucorrhées <strong>mucopurulentes</strong> sont retrouvées en cas de <strong>cervicite</strong> (gonocoque, Chlamydia).</li></ul>"},{"i":"7066fd59243d","n":162,"o":"162-10","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une infection génitale basse chez la femme","q":"Comment se manifeste cliniquement une cervicite chez la femme ?","a":"<p>Une cervicite, souvent causée par le gonocoque ou Chlamydia, se manifeste par :</p><ul><li>Des <strong>leucorrhées mucopurulentes</strong>.</li><li>Une <strong>fragilité du col</strong> utérin.</li><li>Un <strong>ectropion friable hémorragique</strong>, visible à l'examen.</li></ul>"},{"i":"90d7a3ce0aa8","n":162,"o":"162-10","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une infection génitale basse chez la femme","q":"Quels sont les signes cliniques locaux et associés d'une infection à Candida chez la femme ?","a":"<p>En cas d'infection à Candida, les signes cliniques sont :</p><ul><li><strong>Leucorrhées blanches, caséeuses</strong> (ressemblant à du lait caillé).</li><li>Un <strong>prurit intense</strong> (quadruple +) est très fréquent.</li><li>Des signes locaux associés de <strong>vulvite</strong> et d'<strong>anite</strong> peuvent être présents.</li></ul>"},{"i":"af736abe970b","n":162,"o":"162-10","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une infection génitale basse chez la femme","q":"Quels sont les signes cliniques associés à une vaginose bactérienne chez la femme ?","a":"<p>La vaginose bactérienne présente les signes cliniques suivants :</p><ul><li>Des <strong>leucorrhées grisâtres, peu abondantes</strong>.</li><li>Un <strong>prurit rare</strong>.</li><li>Une <strong>odeur de poisson pourri</strong>, particulièrement notable lors du « sniff test ».</li></ul>"},{"i":"e3f74fba723b","n":162,"o":"162-10","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une infection génitale basse chez la femme","q":"Quels signes cliniques typiques une infection à Trichomonas peut-elle présenter chez la femme ?","a":"<p>Une infection à Trichomonas se caractérise par :</p><ul><li>Des <strong>leucorrhées vertes, spumeuses</strong>.</li><li>Un <strong>prurit</strong> et des <strong>brûlures</strong>.</li><li>Une <strong>urétrite</strong> associée.</li><li>Une <strong>odeur de moisi</strong>.</li><li>À l'examen au spéculum, on peut observer une <strong>colpite punctiforme « framboisée » ou « léopard »</strong>, très évocatrice.</li></ul>"},{"i":"0a4d055d721c","n":162,"o":"162-12","u":"Étiologies","t":"Connaître les causes d’infections génitales basses chez la femme","q":"Quelles sont les causes NON-IST des infections génitales basses chez la femme mentionnées dans l'objectif ?","a":"<p>Les causes non-IST des infections génitales basses chez la femme sont la <strong>candidose</strong> (due à <strong>Candida albicans</strong>) et la <strong>vaginose bactérienne</strong> (impliquant <strong>Gardnerella vaginalis</strong> ou <strong>Mycoplasma hominis</strong>).</p>"},{"i":"70fbb6a80ccb","n":162,"o":"162-12","u":"Étiologies","t":"Connaître les causes d’infections génitales basses chez la femme","q":"Quelle est la caractéristique principale distinguant une IST d'une candidose ou d'une vaginose bactérienne en termes d'origine ?","a":"<p>La principale distinction est que les IST proviennent d'une <strong>contamination externe</strong>, tandis que la candidose et la vaginose bactérienne sont des <strong>déséquilibres de la flore vaginale endogène</strong>, notamment une perte des <strong>lactobacilles de Döderlein</strong>, et ne sont donc pas des IST.</p>"},{"i":"fbfb4547eca4","n":162,"o":"162-12","u":"Étiologies","t":"Connaître les causes d’infections génitales basses chez la femme","q":"Quels sont les agents infectieux considérés comme des IST pouvant causer des infections génitales basses chez la femme ?","a":"<p>Les agents étiologiques d'IST pour les infections génitales basses chez la femme sont :</p><ul><li><strong>Trichomonas vaginalis</strong></li><li><strong>Neisseria gonorrhoeae</strong> (gonocoque)</li><li><strong>Chlamydia trachomatis</strong></li><li><strong>Mycoplasma genitalium</strong></li></ul>"},{"i":"1d865c2533b8","n":162,"o":"162-15","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","q":"Quels sont les examens microbiologiques spécifiques pour le diagnostic de l'infection à gonocoque et de l'infection à Chlamydia ?","a":"<ul><li>Pour le <strong>gonocoque</strong> : on réalise un examen direct (coloration de <strong>Gram</strong>), une <strong>culture</strong> (sur gélose chocolat) et une <strong>PCR</strong> (plus sensible).</li><li>Pour la <strong>Chlamydia</strong> : la méthode de référence est la <strong>PCR/TAAN</strong> (amplification des acides nucléiques). La sérologie est inutile.</li></ul>"},{"i":"5969db2822dd","n":162,"o":"162-15","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","q":"Quel est le bilan sérologique systématique à réaliser devant toute suspicion d'IST, quel que soit le sexe et la manifestation clinique ?","a":"<p>Devant toute IST, le bilan sérologique systématique comprend les sérologies :</p><ul><li><strong>VIH</strong></li><li><strong>Syphilis</strong></li><li><strong>VHB</strong></li><li>± <strong>VHC</strong> (selon le contexte)</li></ul>"},{"i":"70ce51429887","n":162,"o":"162-15","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","q":"Comment doit être orientée la recherche de Chlamydia ou de gonocoque en cas d'inflammation urogénitale selon la symptomatologie et le sexe ?","a":"<p>En cas d'inflammation urogénitale :</p><ul><li>Pour un homme présentant un écoulement urétral : <strong>prélèvement urétral</strong> en première intention.</li><li>S'il n'y a pas d'écoulement chez l'homme : <strong>premier jet urinaire</strong>.</li><li>Chez la femme : <strong>prélèvement vaginal ou cervical</strong>.</li></ul>"},{"i":"78cb5d1013d0","n":162,"o":"162-15","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","q":"Quels examens doivent être réalisés en cas de suspicion d'ulcérations génitales et quel est le bilan sérologique complémentaire nécessaire ?","a":"<p>En cas d'ulcérations génitales, les examens à réaliser sont des <strong>prélèvements locaux</strong> au niveau des ulcérations, complétés par une <strong>sérologie de la syphilis</strong>.</p>"},{"i":"98ebae7403dc","n":162,"o":"162-15","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","q":"Quels examens sont à envisager en cas de manifestations extragénitales d'IST ?","a":"<p>En cas de manifestations extragénitales d'IST, les examens peuvent inclure :</p><ul><li>Des <strong>hémocultures</strong>.</li><li>Des <strong>ponctions articulaires</strong> en cas d'atteinte articulaire.</li><li>Un <strong>prélèvement pharyngé</strong> en cas d'atteinte oropharyngée.</li><li>Un <strong>écouvillonnage anal</strong> en cas d'atteinte anale.</li></ul>"},{"i":"d24682688aaf","n":162,"o":"162-15","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en cas d’IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisation extragénitales","q":"Quelles sont les IST dont la déclaration anonyme à l'ARS est obligatoire ?","a":"<p>La déclaration anonyme à l'ARS est obligatoire pour deux IST : la <strong>gonococcie</strong> (infection à gonocoque) et la <strong>syphilis</strong>.</p>"},{"i":"12fa170388b9","n":162,"o":"162-18","u":"Prise en charge","t":"Connaître les modalités du traitement probabiliste des IST","q":"Quel est le traitement probabiliste recommandé pour une infection génitale haute (IGH) chez une patiente présentant des signes d'IST ?","a":"<ul><li><strong>Ceftriaxone IM</strong> en dose unique (pour le gonocoque).</li><li><strong>Doxycycline per os</strong> pendant <strong>10 jours</strong> (pour Chlamydia).</li><li><strong>Métronidazole per os</strong> pendant <strong>10 jours</strong> (pour couvrir les anaérobies).</li></ul>"},{"i":"13e911ea4a87","n":162,"o":"162-18","u":"Prise en charge","t":"Connaître les modalités du traitement probabiliste des IST","q":"Quel est le traitement de première intention recommandé pour une infection à gonocoque confirmée ou suspectée dans un contexte probabiliste ?","a":"<p>Le traitement de première intention est la <strong>Ceftriaxone IM en dose unique</strong>. Les autres céphalosporines de 3ème génération ne sont pas validées dans ce contexte. La <strong>Ciprofloxacine est proscrite</strong> en traitement probabiliste en raison d'une résistance supérieure à 40%.</p>"},{"i":"35a9ba4ecd77","n":162,"o":"162-18","u":"Prise en charge","t":"Connaître les modalités du traitement probabiliste des IST","q":"Quel est le traitement probabiliste recommandé pour une infection génitale basse (IGB), type urétrite ou cervicite, chez un patient présentant des signes d'IST ?","a":"<ul><li><strong>Ceftriaxone IM</strong> en dose unique (pour le gonocoque).</li><li><strong>Doxycycline per os</strong> pendant <strong>7 jours</strong> (pour Chlamydia).</li></ul>"},{"i":"9ffd1d818595","n":162,"o":"162-18","u":"Prise en charge","t":"Connaître les modalités du traitement probabiliste des IST","q":"Quelle est la règle générale pour le traitement probabiliste des IST, notamment concernant les germes couverts ?","a":"<p>Le traitement probabiliste des IST doit toujours couvrir conjointement le <strong>gonocoque</strong> et <strong>Chlamydia trachomatis</strong>, en raison de la fréquence élevée des co-infections.</p>"},{"i":"a8679c87f815","n":162,"o":"162-18","u":"Prise en charge","t":"Connaître les modalités du traitement probabiliste des IST","q":"Quand et pourquoi un contrôle clinique est-il recommandé après un traitement probabiliste d'une IST ?","a":"<p>Un contrôle clinique est recommandé à <strong>J7</strong> (Jour 7) après le début du traitement probabiliste afin d'évaluer la réponse clinique et l'efficacité du traitement.</p>"},{"i":"9bdc6761d472","n":162,"o":"162-19","u":"Prise en charge","t":"Connaître les modalités de dépistage des infections à papillomavirus humain (HPV)","q":"Quel est le délai moyen entre une infection persistante par le HPV et le développement d'un cancer invasif du col de l'utérus ?","a":"<p>Le délai moyen entre une infection persistante par le HPV et le développement d'un cancer invasif du col de l'utérus est d'environ <strong>15 ans</strong>. Cette longue « fenêtre » permet la détection et le traitement des lésions précancéreuses.</p>"},{"i":"c4c8fc30d0ee","n":162,"o":"162-19","u":"Prise en charge","t":"Connaître les modalités de dépistage des infections à papillomavirus humain (HPV)","q":"Comment est organisé le dépistage des lésions cervicales induites par le HPV chez la femme, selon l'âge en France ?","a":"<p>Le dépistage des lésions cervicales induites par le HPV en France est organisé comme suit :</p><ul><li>Entre 25 et 30 ans : par <strong>frottis cervico-utérin</strong> (FCU) cylogique.</li><li>À partir de 30 ans et jusqu'à 65 ans : par test <strong>HPV-HR</strong> (recherche de Papillomavirus Humains à Haut Risque) en dépistage primaire.</li></ul>"},{"i":"ce0b6abb6cdb","n":162,"o":"162-19","u":"Prise en charge","t":"Connaître les modalités de dépistage des infections à papillomavirus humain (HPV)","q":"Chez quelles populations spécifiques doit-on envisager un examen proctologique dans le cadre du dépistage des lésions induites par le HPV ?","a":"<p>Un examen proctologique pour le dépistage des lésions induites par le HPV doit être envisagé chez :</p><ul><li>Les <strong>Hommes ayant des Relations Sexuelles avec des Hommes (HSH)</strong>.</li><li>Les <strong>femmes avec des antécédents de dysplasie cervicale</strong>, particulièrement si elles sont <strong>VIH+</strong>.</li></ul>"},{"i":"180dd525fa1b","n":162,"o":"162-20","u":"Prise en charge","t":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","q":"Comment traiter une infection à Trichomonas vaginalis documentée microbiologiquement ?","a":"<p>Le traitement de l'infection à Trichomonas vaginalis documentée repose sur le <strong>Métronidazole</strong> par voie orale (PO) soit en dose unique de <strong>2 g</strong>, soit pendant <strong>7 à 10 jours</strong>. Le <strong>Secnidazole</strong> (2 g en dose unique) est une alternative. Il est impératif de <strong>traiter également le ou les partenaires</strong>.</p>"},{"i":"262202807a99","n":162,"o":"162-20","u":"Prise en charge","t":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","q":"Quel est le protocole de traitement recommandé pour le Mycoplasma genitalium documenté chez les patients symptomatiques ?","a":"<p>Chez les patients symptomatiques, le protocole de traitement du Mycoplasma genitalium documenté est séquentiel : <strong>Doxycycline</strong> pendant <strong>7 jours</strong>, suivie par l'<strong>Azithromycine</strong>.</p>"},{"i":"507a76203fe1","n":162,"o":"162-20","u":"Prise en charge","t":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","q":"Quel est le traitement antibiotique de la Chlamydia trachomatis après documentation microbiologique ?","a":"<p>Le traitement antibiotique de la Chlamydia trachomatis documentée est la <strong>Doxycycline</strong> par voie orale (PO) à raison de <strong>200 mg/jour</strong> pendant <strong>7 jours</strong>.</p>"},{"i":"634dbef97b93","n":162,"o":"162-20","u":"Prise en charge","t":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","q":"Quel est le traitement recommandé pour le gonocoque en cas d'allergie aux céphalosporines de 3ème génération ?","a":"<p>En cas d'allergie aux céphalosporines de 3ème génération, le traitement de 2ème intention pour le gonocoque est la <strong>Gentamicine</strong> en intra-musculaire (IM) en dose unique.</p>"},{"i":"8f94a635ea45","n":162,"o":"162-20","u":"Prise en charge","t":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","q":"Quelle est la règle systématique à respecter lors du traitement d'une infection à gonocoque ?","a":"<p>La règle d'or est qu'un <strong>traitement anti-Chlamydia est systématiquement associé</strong> au traitement du gonocoque, même en l'absence de documentation pour Chlamydia au départ.</p>"},{"i":"d4e3c8ce8161","n":162,"o":"162-20","u":"Prise en charge","t":"Connaître les modalités de choix des antibiotiques après documentation microbiologique de l’IST","q":"Quel est le traitement de première intention du gonocoque suite à une documentation microbiologique ?","a":"<p>Le traitement de première intention du gonocoque documenté est la <strong>Ceftriaxone</strong> en intra-musculaire (IM) en dose unique.</p>"},{"i":"44dd5daf54f8","n":162,"o":"162-23","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une syphilis précoce","q":"Quelles sont les principales manifestations cutanéo-muqueuses de la syphilis secondaire ?","a":"<ul><li>La <strong>roséole syphilitique</strong> : il s'agit de macules rose pâle, fugaces, situées sur le tronc (première éruption).</li><li>Les <strong>syphilides papuleuses</strong> : elles sont de couleur cuivrée, avec une forme <strong>palmo-plantaire très évocatrice</strong> dans environ 30% des cas.</li><li>Les syphilides génitales : elles sont très contagieuses, indolores et multiples.</li><li>Des manifestations cutanéo-phanériennes : une fausse perlèche, une <strong>alopécie en fourrure mitée</strong> et une dépilation des sourcils.</li></ul>"},{"i":"4d4d27673f06","n":162,"o":"162-23","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une syphilis précoce","q":"Quelle est la définition de la syphilis précoce et à quelle bactérie est-elle due ?","a":"<p>La syphilis précoce correspond à la syphilis survenant dans la première année d'infection. Elle regroupe la syphilis primaire, la syphilis secondaire et la syphilis latente précoce. Elle est causée par <strong>Treponema pallidum</strong>, un spirochète trés contagieux et non immunisant.</p>"},{"i":"64a204917f75","n":162,"o":"162-23","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une syphilis précoce","q":"Quels sont les signes cliniques caractéristiques de la syphilis primaire ?","a":"<ul><li>Un <strong>chancre syphilitique</strong> : Il est typiquement <strong>indolore</strong>, unique, de <strong>5 à 15 mm</strong>, <strong>induré</strong> et à fond propre rosé.</li><li>Une <strong>adénopathie satellite inguinale</strong> : Elle est unilatérale et non inflammatoire.</li></ul>"},{"i":"7e45e7bc53c3","n":162,"o":"162-23","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une syphilis précoce","q":"Quels sont les signes généraux pouvant être associés à la syphilis secondaire ?","a":"<ul><li>Un <strong>fébricule</strong>.</li><li>Des <strong>polyadénopathies</strong>.</li><li>Une <strong>hépato-splénomégalie</strong>.</li></ul>"},{"i":"05c05047425c","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Comment interpréter un profil sérologique TT-/TNT- dans le diagnostic de la syphilis ?","a":"<p>Un profil <strong>TT-/TNT-</strong> peut indiquer plusieurs situations :</p><ul><li>Une <strong>absence de tréponématose</strong>.</li><li>Une infection <strong>très récente</strong> (dans les 5 à 15 premiers jours), nécessitant de répéter la sérologie à 1 ou 2 semaines.</li><li>Une tréponématose <strong>guérie et traitée précocement</strong>.</li></ul>"},{"i":"1eae8812626d","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Quelles sont les principales causes de faux positifs des tests non tréponémiques (VDRL/RPR) pour la syphilis ?","a":"<p>Les causes de <strong>faux positifs</strong> des tests non tréponémiques (VDRL/RPR) sont variées et incluent :</p><ul><li>Le <strong>lupus</strong>.</li><li>Le <strong>SAPL</strong> (Syndrome des Anti-Phospholipides).</li><li>La <strong>grossesse</strong>.</li><li>L'infection par le <strong>VIH</strong>.</li><li>D'autres <strong>infections</strong> (lèpre, tuberculose, mononucléose infectieuse, paludisme).</li><li>La <strong>toxicomanie intraveineuse</strong>.</li><li>Une <strong>gammapathie</strong>.</li></ul>"},{"i":"28a8642bdf48","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Quelle est la signification d'un profil sérologique TT+/TNT- dans le diagnostic de la syphilis ?","a":"<p>Un profil <strong>TT+/TNT-</strong> peut correspondre à :</p><ul><li>Une <strong>cicatrice sérologique</strong> d'une tréponématose antérieurement guérie.</li><li>Une <strong>syphilis très précoce</strong> (où le VDRL n'est pas encore positif).</li><li>Une syphilis <strong>tertiaire ancienne</strong>.</li></ul>"},{"i":"5531acab42df","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Que signifie un profil sérologique TT+/TNT+ pour le diagnostic de la syphilis ?","a":"<p>Un profil <strong>TT+/TNT+</strong> indique une <strong>tréponématose</strong>. L'interprétation doit se faire en fonction du <strong>titre du VDRL</strong>, qui reflète l'activité de la maladie (traitée ou non, guérie ou non).</p>"},{"i":"7b7c6ffa9c64","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Quelles sont les différences de spécificité, de marqueur d'activité et de temps de positivation entre les tests tréponémiques et non tréponémiques pour le diagnostic de la syphilis ?","a":"<ul><li><strong>Spécificité</strong> : Les <strong>TT</strong> sont spécifiques des <strong>tréponématoses</strong> (mais pas de la syphilis seule). Les <strong>TNT</strong> sont <strong>non spécifiques</strong>.</li><li><strong>Marqueur d'activité</strong> : Les <strong>TT ne sont pas des marqueurs d'activité</strong> (restent positifs après guérison). Les <strong>TNT</strong> sont des <strong>marqueurs d'activité</strong> et sont utilisés pour le suivi du traitement.</li><li><strong>Positivation</strong> : Les <strong>TT se positivent 7 à 10 jours</strong> après le chancre (le <strong>FTA dès 5-8 jours</strong>). Les <strong>TNT se positivent 10 à 15 jours</strong> après le chancre.</li></ul>"},{"i":"8daa671edcd4","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Comment les tests sérologiques de la syphilis sont-ils classés, et quels sont les exemples pour chaque catégorie ?","a":"<p>Les tests sérologiques de la syphilis sont classés en deux catégories :</p><ul><li>Les tests <strong>tréponémiques (TT)</strong> : <ul><li>TPHA (Treponema Pallidum Hemagglutination Assay)</li><li>ELISA (Enzyme-Linked Immunosorbent Assay)</li><li>EIA (Enzyme Immunoassay)</li><li>FTA (Fluorescent Treponemal Antibody)</li></ul></li><li>Les tests <strong>non tréponémiques (TNT)</strong> : <ul><li>VDRL (Venereal Disease Research Laboratory)</li><li>RPR (Rapid Plasma Reagin)</li></ul></li></ul>"},{"i":"9ce82b68c1a1","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Quelle est la stratégie pratique de dépistage sérologique de la syphilis et quels sont les avantages et inconvénients du test FTA ?","a":"<p>En pratique, l'<strong>ELISA</strong> est réalisé en <strong>première intention</strong>. Si le test ELISA est positif, un <strong>VDRL</strong> est effectué pour évaluer l'activité de l'infection. Le <strong>FTA</strong> est un test tréponémique à <strong>positivation précoce (5-8 jours)</strong> et est utile en cas de contage récent avec TPHA/VDRL négatifs, suggérant une syphilis primaire très précoce. Son inconvénient est qu'il nécessite un <strong>microscope à fluorescence</strong>, ce qui le rend plus coûteux.</p>"},{"i":"bf236ee41652","n":162,"o":"162-27","u":"Examens complémentaires","t":"Connaître les tests sérologiques au cours de la syphilis","q":"Comment interpréter un profil sérologique TT-/TNT+ dans le contexte de la syphilis ?","a":"<p>Un profil <strong>TT-/TNT+</strong> peut signifier :</p><ul><li>Un <strong>faux positif</strong> du VDRL (appelé \"fausse sérologie\").</li><li>Une <strong>syphilis primaire très précoce</strong>, où le VDRL peut être positif avant les tests tréponémiques (environ <strong>10%</strong> des cas).</li></ul>"},{"i":"0fd737c62ddd","n":162,"o":"162-28","u":"Prise en charge","t":"Connaître les modalités du traitement de la syphilis primaire","q":"Comment doit être gérée une ulcération génitale suspecte de syphilis ?","a":"<p>Devant une ulcération génitale, le traitement doit être initié <strong>sans attendre les résultats de la sérologie</strong>, après avoir effectué les prélèvements diagnostiques.</p>"},{"i":"56589e66436b","n":162,"o":"162-28","u":"Prise en charge","t":"Connaître les modalités du traitement de la syphilis primaire","q":"Quel traitement est préconisé en cas d'allergie à la pénicilline pour la syphilis primaire ?","a":"<p>En cas d'allergie à la pénicilline pour la syphilis primaire, la <strong>doxycycline</strong> par voie orale est préconisée pendant <strong>14 jours</strong>.</p>"},{"i":"8f7b3509ae16","n":162,"o":"162-28","u":"Prise en charge","t":"Connaître les modalités du traitement de la syphilis primaire","q":"Qu'est-ce que la réaction de Jarisch-Herxheimer, et comment la distinguer d'une allergie à la pénicilline dans le contexte d'un traitement de la syphilis ?","a":"<p>La réaction de Jarisch-Herxheimer est une réaction bénigne caractérisée par fièvre, céphalées et myalgies survenant dans les heures suivant la première injection d'antibiotique en raison de la lyse des tréponèmes. Elle ne doit pas être confondue avec une allergie à la pénicilline, qui présente des manifestations différentes (cutanées, respiratoires, cardiovasculaires).</p>"},{"i":"cb07b665a625","n":162,"o":"162-28","u":"Prise en charge","t":"Connaître les modalités du traitement de la syphilis primaire","q":"Quel est l'objectif du suivi après traitement d'une syphilis primaire et comment est-il évalué ?","a":"<p>L'objectif du suivi est la guérison de la syphilis primaire. Elle est évaluée par un <strong>VDRL quantitatif</strong>, dont la négativation à <strong>1 an</strong> confirme la guérison.</p>"},{"i":"ef3b84c5bce1","n":162,"o":"162-28","u":"Prise en charge","t":"Connaître les modalités du traitement de la syphilis primaire","q":"Quel est le traitement de première intention de la syphilis primaire ?","a":"<p>Le traitement de première intention de la syphilis primaire est la <strong>pénicilline G retard</strong> (benzathine-benzylpénicilline) à la dose de <strong>2,4 MUI</strong> en une injection intramusculaire unique.</p>"},{"i":"333960b3f92b","n":162,"o":"162-3","u":"Prise en charge","t":"Connaître les mesures préventives des IST","q":"Quelle est l'approche systématique à adopter lors de toute consultation pour une IST ?","a":"<p>Toute consultation pour une IST doit être saisie comme une opportunité pour :</p><ul><li>Proposer systématiquement le <strong>dépistage du VIH</strong>.</li><li>Proposer systématiquement le <strong>dépistage de la syphilis</strong>.</li><li>Proposer systématiquement le <strong>dépistage du VHB</strong>.</li><li>Vérifier le <strong>statut vaccinal</strong> du patient et proposer les vaccins nécessaires (HPV, VHB, VHA).</li><li>Assurer l'<strong>éducation du patient</strong> et la <strong>notification aux partenaires</strong> sexuels récents pour limiter la transmission.</p></li></ul>"},{"i":"614c7b763f1b","n":162,"o":"162-3","u":"Prise en charge","t":"Connaître les mesures préventives des IST","q":"Quelle est l'importance de la vaccination dans la prévention des IST ?","a":"<p>La vaccination est un pilier de la prévention des IST. Elle est recommandée pour :</p><ul><li>Le <strong>Papillomavirus humain (HPV)</strong>, responsable de lésions précancéreuses, cancéreuses et de condylomes.</li><li>Le <strong>Virus de l'Hépatite B (VHB)</strong>, pouvant provoquer des hépatites aiguës et chroniques.</li><li>Le <strong>Virus de l'Hépatite A (VHA)</strong>, particulièrement chez les hommes ayant des relations sexuelles avec des hommes (HSH) en raison de la contamination possible par rapports bucco-anaux.</li></ul>"},{"i":"a491a4233d6a","n":162,"o":"162-3","u":"Prise en charge","t":"Connaître les mesures préventives des IST","q":"Quelles sont les mesures préventives individuelles des infections sexuellement transmissibles (IST) ?","a":"<p>Les mesures préventives individuelles des IST incluent :</p><ul><li>L'utilisation de <strong>préservatifs masculins et féminins</strong> (méthode de référence).</li><li>Le <strong>dépistage régulier</strong> en cas d'expositions répétées.</li><li>La <strong>vaccination</strong> contre le HPV, le VHB et le VHA (notamment proposée aux hommes ayant des relations sexuelles avec des hommes - HSH).</li><li>La <strong>prophylaxie pré-exposition (PrEP)</strong> anti-VIH en cas de prises de risque régulières.</li></ul>"},{"i":"ced3c1596124","n":162,"o":"162-3","u":"Prise en charge","t":"Connaître les mesures préventives des IST","q":"Qu'est-ce que la PrEP et dans quel contexte est-elle indiquée pour prévenir les IST ?","a":"<p>La <strong>PrEP (prophylaxie pré-exposition)</strong> est une stratégie de prévention des IST concernant spécifiquement le <strong>VIH</strong>. Elle consiste en la prise d'un traitement antirétroviral avant une exposition sexuelle pour réduire le risque de contracter le VIH. Elle est indiquée chez les personnes ayant des <strong>prises de risque régulières</strong>.</p>"},{"i":"9b75dd0720e6","n":162,"o":"162-30","u":"Diagnostic positif","t":"Connaître les manifestations cliniques liées au HPV","q":"Quelles sont les lésions précancéreuses associées à l'HPV et les génotypes impliqués ?","a":"<p>Les lésions précancéreuses associées à l'HPV sont les <strong>néoplasies intra-épithéliales</strong> (cervicales, vulvaires, anales, péniennes). Elles sont causées par les génotypes HPV à <strong>haut risque</strong> (HR), principalement le <strong>16 et le 18</strong>.</p><p>La <strong>papulose bowénoïde</strong> est une forme de dysplasie sévère de l'adulte jeune, également associée aux HPV de type <strong>16 et 18</strong>.</p>"},{"i":"a785aa103b80","n":162,"o":"162-30","u":"Diagnostic positif","t":"Connaître les manifestations cliniques liées au HPV","q":"Quels sont les principaux types de lésions muqueuses anogénitales bénignes associées à l'HPV ?","a":"<p>Les principales lésions muqueuses anogénitales bénignes sont :</p><ul><li>Les <strong>condylomes acuminés</strong>, ou « crêtes-de-coq », qui se présentent comme des masses charnues à verrucosités kératosiques, principalement associés aux HPV de type <strong>6 et 11</strong>.</li><li>Les <strong>condylomes plans</strong>, qui sont des macules-papules rosées, visibles après application d'acide acétique, également associés aux HPV de type <strong>6 et 11</strong>.</li></ul>"},{"i":"cbfb6a443a3d","n":162,"o":"162-30","u":"Diagnostic positif","t":"Connaître les manifestations cliniques liées au HPV","q":"Quels sont les différents types de lésions cutanées bénignes causées par l'HPV ?","a":"<p>Les lésions cutanées bénignes (verrues) causées par l'HPV incluent :</p><ul><li>La <strong>myrmécie</strong>, associée au <strong>HPV1</strong>.</li><li>La <strong>verrue mosaïque</strong>, associée au <strong>HPV2</strong>.</li><li>Les <strong>verrues vulgaires</strong>, également associées au <strong>HPV2</strong>.</li><li>Les <strong>verrues planes</strong>, associées au <strong>HPV3</strong>.</li></ul>"},{"i":"274477e617aa","n":162,"o":"162-35","u":"Suivi et/ou pronostic","t":"Connaître les principales conséquences à long terme des IGH chez la femme","q":"Quel est l'impact d'un premier épisode d'IGH sur le risque de récidive et quel est le pronostic global des IST ?","a":"<ul><li>Le risque de récidive d'IGH est <strong>majoré après un premier épisode</strong>.</li><li>Le pronostic des IST est principalement <strong>fonctionnel</strong> (notamment la stérilité chez la femme) et peut être <strong>vital</strong> dans certains cas (ex: <strong>VIH</strong>, exceptionnellement la gonococcémie disséminée).</li></ul>"},{"i":"7ab2759aec3c","n":162,"o":"162-35","u":"Suivi et/ou pronostic","t":"Connaître les principales conséquences à long terme des IGH chez la femme","q":"Quelle est la principale étiologie des stérilités tubaires et quelle est sa part attribuable aux IGH ?","a":"<p>La <strong>Chlamydia</strong> est la principale étiologie des stérilités tubaires, responsable d'environ <strong>70 %</strong> des cas suite à une IGH.</p>"},{"i":"bcba68510585","n":162,"o":"162-35","u":"Suivi et/ou pronostic","t":"Connaître les principales conséquences à long terme des IGH chez la femme","q":"Quelles sont les principales conséquences à long terme des infections génitales hautes (IGH) chez la femme, même en l'absence de complication aiguë ?","a":"<p>Les IGH exposent à des séquelles tubaires définitives en raison de phénomènes immuno-inflammatoires, même en cas de forme non compliquée. Les principales conséquences sont :</p><ul><li>La <strong>stérilité tubaire</strong>.</li><li>La <strong>grossesse extra-utérine (GEU)</strong>.</li><li>Les <strong>douleurs pelviennes chroniques</strong>.</li></ul>"},{"i":"6afe248e981c","n":162,"o":"162-4","u":"Prise en charge","t":"Connaître les principes de prise en charge du ou des partenaires","q":"Comment doit-on gérer les partenaires d'un patient atteint de Chlamydia trachomatis ?","a":"<p>Pour une infection à <em>Chlamydia trachomatis</em>, le ou les partenaires réguliers doivent être <strong>traités d'emblée</strong>.</p>"},{"i":"d49cec30d6f3","n":162,"o":"162-4","u":"Prise en charge","t":"Connaître les principes de prise en charge du ou des partenaires","q":"Comment prend-on en charge les partenaires d'un patient atteint de syphilis en fonction de la date du dernier rapport sexuel à risque ?","a":"<p>Pour une syphilis :</p><ul><li>Si le dernier rapport sexuel à risque date de <strong>moins de 6 semaines</strong> et que la syphilis est certaine : le partenaire reçoit d'emblée <strong>une injection intramusculaire de pénicilline G retard</strong>, puis une sérologie est réalisée.</li><li>Si le dernier rapport sexuel à risque date de <strong>plus de 6 semaines</strong>, ou si la syphilis est douteuse : le partenaire doit faire une <strong>sérologie</strong>. Il est traité si celle-ci est positive, sinon un recontrôle à 3 mois est effectué.</li></ul>"},{"i":"ee0ea5820391","n":162,"o":"162-4","u":"Prise en charge","t":"Connaître les principes de prise en charge du ou des partenaires","q":"Les partenaires d'un patient infecté par le HPV doivent-ils subir un dépistage spécifique et systématique lié à l'exposition récente ?","a":"<p>Non, il n'y a <strong>pas de dépistage particulier</strong> des partenaires pour l'HPV lié aux rapports récents. Les indications de dépistage chez les partenaires sont indépendantes de l'exposition récente.</p>"},{"i":"f54150b1c2a3","n":162,"o":"162-4","u":"Prise en charge","t":"Connaître les principes de prise en charge du ou des partenaires","q":"Quelle est la conduite à tenir face aux partenaires d'un patient ayant une gonococcie ?","a":"<p>Pour une gonococcie, les partenaires doivent bénéficier d'un <strong>dépistage</strong>, et peuvent recevoir un <strong>traitement antibiotique</strong> en probabiliste.</p>"},{"i":"2337d37f3678","n":162,"o":"162-7","u":"Contenu multimédia","t":"Photographie d’un chancre (syphilis primaire)","q":"Quelles sont les localisations typiques d'un chancre syphilitique primaire ?","a":"<p>Les localisations les plus fréquentes du chancre syphilitique primaire sont :</p><ul><li>Chez l'homme : le <strong>sillon balano-préputial</strong>.</li><li>Chez la femme : la <strong>partie externe de la vulve</strong>.</li><li>D'autres localisations sont possibles, notamment <strong>anales, buccales ou pharyngées</strong>, en fonction du ou des sites d'inoculation de <em>Treponema pallidum</em>.</li></ul>"},{"i":"2882e846dd02","n":162,"o":"162-7","u":"Contenu multimédia","t":"Photographie d’un chancre (syphilis primaire)","q":"Quelles sont les principales caractéristiques cliniques d'un chancre syphilitique primaire ?","a":"<p>Un chancre syphilitique primaire se caractérise par :</p><ul><li>Une lésion <strong>indolore</strong> (contrairement à l'herpès ou au chancre mou).</li><li>Généralement <strong>unique</strong>, mais parfois multiple (en miroir).</li><li>Une taille de <strong>5 à 15 mm</strong>.</li><li>Un fond <strong>propre et rosé</strong> (contrairement au chancre mou à fond sale).</li><li>Une <strong>induration marquée</strong> au toucher, qui est le caractère le plus évocateur.</li></ul>"},{"i":"a9e8fb56827c","n":162,"o":"162-7","u":"Contenu multimédia","t":"Photographie d’un chancre (syphilis primaire)","q":"Quelle est la particularité des adénopathies associées à un chancre syphilitique primaire ?","a":"<p>Le chancre syphilitique primaire est souvent associé à une <strong>adénopathie satellite inguinale</strong>. Celle-ci est caractéristique : elle est <strong>unilatérale</strong> et <strong>non inflammatoire</strong>, c'est-à-dire non douloureuse et non rouge.</p>"},{"i":"0aaa5adafd51","n":162,"o":"162-8","u":"Diagnostic positif","t":"Connaître les signes cliniques de l’urétrite masculine","q":"Quels sont les signes cliniques orientant vers une urétrite masculine à gonocoque ?","a":"<ul><li>Un <strong>écoulement d'allure purulente et abondant</strong>, présent dans 90% des cas.</li><li>Un tableau clinique <strong>bruyant</strong>, avec des <strong>brûlures mictionnelles intenses</strong>, une <strong>dysurie</strong>, un <strong>prurit urétral</strong> et une <strong>méatite</strong>.</li><li>Une incubation <strong>courte</strong>, de l'ordre de 2 à 7 jours.</li></ul>"},{"i":"38fc2d7defe7","n":162,"o":"162-8","u":"Diagnostic positif","t":"Connaître les signes cliniques de l’urétrite masculine","q":"Comment est définie une urétrite masculine sur le plan biologique ?","a":"<p>Une urétrite masculine est définie biologiquement par la présence de <strong>plus de 5 polynucléaires neutrophiles (PNN)</strong> au frottis urétral (au grossissement 100) ou de <strong>plus de 10 PNN</strong> (au grossissement 400).</p>"},{"i":"6a50e74e69e6","n":162,"o":"162-8","u":"Diagnostic positif","t":"Connaître les signes cliniques de l’urétrite masculine","q":"Quelle est la définition clinique de l'urétrite masculine ?","a":"<p>L'urétrite masculine est définie par l'association de <strong>signes fonctionnels urétraux</strong> et d'un <strong>écoulement urétral</strong>.</p>"},{"i":"d35f67b981dd","n":162,"o":"162-8","u":"Diagnostic positif","t":"Connaître les signes cliniques de l’urétrite masculine","q":"Quels sont les signes cliniques orientant vers une urétrite masculine à Chlamydia ?","a":"<ul><li>Un <strong>écoulement clair, modéré et intermittent</strong>, présent dans moins de 50% des cas.</li><li>Un tableau clinique <strong>souvent peu bruyant, voire asymptomatique</strong> dans environ 50% des cas.</li><li>Une incubation de <strong>quelques jours à quelques mois</strong>, souvent plus longue que pour le gonocoque.</li></ul>"}]};